// ================= 식단 =================
const slotFilled=(m,k)=>!!(m&&m.slots&&m.slots[k]&&(m.slots[k].photo||(m.slots[k].foods||[]).length));
const LEVELS=['새싹','루키','챌린저','러너','프로','엘리트','마스터','레전드'];
const BADGES=[['🌱','첫 기록',s=>s.records>=1],['🔥','3일 연속',s=>s.longest>=3],['⚡','7일 연속',s=>s.longest>=7],['🏆','14일 연속',s=>s.longest>=14],['👑','30일 연속',s=>s.longest>=30],['💯','완벽한 하루',s=>s.perfect>=1],['🏅','완벽 10일',s=>s.perfect>=10],['👍','칭찬 10개',s=>s.likes>=10],['📸','기록 100회',s=>s.records>=100]];
function mealStats(d){const filled=dt=>{const m=d.meals[dt];return m&&SLOTS.some(s=>slotFilled(m,s[0]))};let streak=0,c=today();if(!filled(c))c=addDays(c,-1);let g=0;while(filled(c)&&g++<999){streak++;c=addDays(c,-1)}
 const days=Object.keys(d.meals).filter(filled).sort();let longest=0,run=0,prev=null;for(const x of days){run=prev&&addDays(prev,1)===x?run+1:1;longest=Math.max(longest,run);prev=x}
 let records=0,perfect=0,likes=0;for(const m of Object.values(d.meals)){records+=SLOTS.filter(s=>slotFilled(m,s[0])).length;if(['breakfast','lunch','dinner'].every(k=>slotFilled(m,k)))perfect++;likes+=Object.values(m.review||{}).filter(r=>r&&r.ok).length}
 const pts=records*10+likes*5+perfect*10+longest*5;const lv=Math.floor(pts/150)+1;return {streak,longest,records,perfect,likes,pts,lv,title:LEVELS[Math.min(LEVELS.length-1,lv-1)],next:150-(pts%150)}}
function guessSlot(){const h=new Date().getHours();return h<10?'breakfast':h<15?'lunch':h<17?'snack':h<21?'dinner':'snack'}
const mealSum=(m,key)=>SLOTS.reduce((a,[k])=>a+((m?.slots?.[k]?.foods)||[]).reduce((x,f)=>x+(+f[key]||0),0),0);
const activePlan=d=>d.diet?.plan||d.diet?.aiPlan||null;
function vDiet(mid,adm){if(adm){const cur=subOf('adiet','plan');return `${seg('adiet',[['plan','식단표 등록'],['today','식단 기록 확인'],['ai','AI 식단']],'plan')}${cur==='today'?dietToday(mid,true):cur==='ai'?dietAI(mid):dietPlanAdmin(mid)}`}
 const cur=subOf('diet','today');return `${seg('diet',[['today','오늘 기록'],['plan','내 식단표'],['search','칼로리 검색'],['ai','AI 식단']],'today')}${cur==='plan'?dietPlanView(mid):cur==='search'?foodSearchSec(mid):cur==='ai'?dietAI(mid):dietToday(mid,false)}`}
function dietToday(mid,adm){const d=md(mid);const date=S.dietDate||today();const meal=d.meals[date];const st=mealStats(d);const plan=activePlan(d);const kcal=Math.round(mealSum(meal,'k'));const tgt=+plan?.kcal||0;const week=[...Array(7)].map((_,i)=>addDays(today(),i-6));
 return `${adm?'':`<div class="card hero sun"><div class="lvl"><div class="lv">${st.lv}</div><div class="grow"><div class="b" style="font-size:17px">Lv.${st.lv} ${st.title}</div><div class="xs muted">${st.pts}P · 다음 레벨까지 ${st.next}P</div><div class="bar" style="background:rgba(255,255,255,.3);margin-top:7px"><i style="width:${(150-st.next)/150*100}%;background:#fff"></i></div></div><div style="text-align:center"><div style="font-size:28px;font-weight:900">🔥${st.streak}</div><div class="xs muted">연속 기록</div></div></div></div>`}
 <div class="card"><div class="row sb"><h3>최근 7일</h3><span class="xs muted">완벽한 하루 ${st.perfect}회 · 칭찬 ${st.likes}개</span></div><div class="week">${week.map(w=>`<div class="tap" data-a="dietGo" data-d="${w}"><div class="d" style="${w===date?'color:var(--pri)':''}">${DOW[parseD(w).getDay()]}</div><div class="ds">${SLOTS.map(([k])=>`<i class="${slotFilled(d.meals[w],k)?'on':''}"></i>`).join('')}</div></div>`).join('')}</div>
 ${adm?'':`<div class="badges">${BADGES.map(([i,n,f])=>`<div class="badge ${f(st)?'on':''}"><div class="bi">${i}</div>${n}</div>`).join('')}</div>`}</div>
 <div class="card"><div class="row sb nw"><button class="ib sm" data-a="dietDay" data-v="-1">${ic('left')}</button><div style="text-align:center"><b>${fmtD(date)}</b>${date===today()?'<div class="xs pc b">오늘</div>':''}</div><button class="ib sm" data-a="dietDay" data-v="1">${ic('right')}</button></div>
 <div class="row sb"><div><span class="big num">${kcal}</span><span class="muted sm"> ${tgt?`/ ${tgt} kcal`:'kcal'}</span></div><div class="xs muted num">탄 ${Math.round(mealSum(meal,'c'))}g · 단 ${Math.round(mealSum(meal,'p'))}g · 지 ${Math.round(mealSum(meal,'f'))}g</div></div>
 ${tgt?`<div class="bar"><i style="width:${Math.min(100,kcal/tgt*100)}%;${kcal>tgt*1.1?'background:var(--hot)':''}"></i></div>`:''}</div>
 ${!adm&&S.aiLeft&&!S.aiLeft.admin&&S.aiLeft.mealLimit?`<p class="xs muted" style="margin:0 4px 8px">${ic('spark',12)} 오늘 사진 AI 분석 <b>${S.aiLeft.meal}</b>/${S.aiLeft.mealLimit}회 남음</p>`:''}<div class="mgrid">${SLOTS.map(s=>mealSlot(mid,date,meal,s,adm)).join('')}</div>`}
function mealSlot(mid,date,meal,[k,l,e],adm){const s=meal?.slots?.[k]||{};const rv=meal?.review?.[k]||{};const done=slotFilled(meal,k);const bk=`ml_${mid}_${date}_${k}`;const A2=s.ai||{};const T=A2.total;const busyAI=S.busy['ai'+bk];
 const thumb=S.busy[bk]?`<div class="mth mthe"><span class="spin"></span></div>`:s.photo?`<button class="mth" data-a="mealView" data-m="${mid}" data-d="${date}" data-s="${k}" aria-label="${l} 음식 분석 보기"><img src="${fileUrl(s.photo)}" alt="${l} 사진"></button>`:adm?`<div class="mth mthe">${ic('cam',20)}</div>`:`<label class="mth mthe" aria-label="${l} 사진 올리기">${ic('cam',22)}<input type="file" accept="image/*" hidden data-file="mealPhoto" data-m="${mid}" data-d="${date}" data-s="${k}"></label>`;
 const sub=busyAI?'<span class="xs muted"><span class="spin sm"></span> 음식 분석 중…</span>':T?`<span class="xs num"><b>${Math.round(T.kcal||0)}</b>kcal · 탄${Math.round(T.carbs||0)} 단${Math.round(T.protein||0)} 지${Math.round(T.fat||0)}g${A2.score?` · ${'★'.repeat(Math.max(0,Math.min(5,+A2.score)))}`:''}</span>`:s.photo?'<span class="xs pc b">눌러서 음식 분석 보기</span>':`<span class="xs muted">${adm?'기록 없음':'사진을 올리면 AI가 분석해요'}</span>`;
 return `<div class="mslot ${done?'done':''}"><div class="mrow">${thumb}<div class="grow" style="min-width:0">${s.photo?`<button class="mtt" data-a="mealView" data-m="${mid}" data-d="${date}" data-s="${k}">${e} ${l} ${ic('right',14)}</button>`:`<b class="mtt0">${e} ${l}</b>`}<div>${sub}</div></div>${rv.ok?'<span class="chip g">👍</span>':s.at?`<span class="xs muted">${ago(s.at)}</span>`:''}</div>
 ${(()=>{const fs=s.foods||[];if(!fs.length)return '';const open=(S.mfOpen||{})[bk];const tk=Math.round(fs.reduce((a,f)=>a+(+f.k||0)*(+f.q||1),0));
  const head=`<button class="mftog" data-a="mfTog" data-k="${bk}" aria-expanded="${open?'true':'false'}"><span class="grow">음식 ${fs.length}개 · <b class="num">${tk}kcal</b></span><span class="xs pc b">${open?'접기':'펼치기'}</span><span style="display:inline-flex;transform:rotate(${open?-90:90}deg)">${ic('right',14)}</span></button>`;
  return head+(open?fs.map((f,i)=>`<div class="food"><span class="grow">${esc(f.n)} <span class="xs muted">${f.q&&f.q!=1?`×${f.q}`:''}${f.ai?' · AI추정':''}</span></span><span class="num sm b">${Math.round(f.k)}kcal</span>${adm?'':`<button class="x" data-a="foodDel" data-m="${mid}" data-d="${date}" data-s="${k}" data-i="${i}" aria-label="삭제">×</button>`}</div>`).join(''):'')})()}
 ${rv.comment?`<div class="cmt adm"><b class="xs pc">트레이너</b><div class="sm">${esc(rv.comment)}</div></div>`:''}
 ${adm?`<div class="row nw"><button class="btn sm ${rv.ok?'pri':''}" data-a="mealLike" data-m="${mid}" data-d="${date}" data-s="${k}" aria-label="칭찬">👍</button><input class="inp" style="padding:8px 10px;font-size:14px" placeholder="코멘트" data-f="rv_${bk}" value="${esc(fv('rv_'+bk,rv.comment||''))}"><button class="btn sm" data-a="mealCmt" data-m="${mid}" data-d="${date}" data-s="${k}">저장</button></div>`
 :`<div class="row"><button class="btn sm soft" data-a="foodPick" data-m="${mid}" data-d="${date}" data-s="${k}">${ic('plus',14)} 음식</button>${s.photo?`<label class="btn sm ghost">${ic('cam',14)} 사진 변경<input type="file" accept="image/*" hidden data-file="mealPhoto" data-m="${mid}" data-d="${date}" data-s="${k}"></label>`:''}</div>`}</div>`}
// ---- 식단 사진 AI 분석 ----
const NUTRI_PROMPT=(label,plan)=>`이 사진은 회원의 ${label} 식사다. 사진에 보이는 음식을 하나씩 알아보고 각 음식의 양(그램 또는 1인분 단위)을 사진에서 추정한 뒤 영양 성분을 계산하라. 한국 음식은 한국 영양 성분 기준으로 추정한다.${plan?` 회원의 하루 목표는 ${plan.kcal||'?'}kcal${plan.rules&&plan.rules.length?`, 식단 규칙: ${plan.rules.slice(0,5).join(' / ')}`:''}.`:''}
모든 숫자는 숫자형. 탄수화물·단백질·지방·당류·식이섬유는 g, 나트륨은 mg, 칼로리는 kcal.
score(1~5)는 균형과 목표 적합도. good는 잘한 점 1~3개, improve는 개선 제안 1~3개(구체적으로, 대체 음식 포함), feedback은 칭찬을 섞은 1~2문장. confidence는 "높음"|"보통"|"낮음"(사진이 흐리거나 양을 알기 어려우면 낮음). 음식이 아니면 foods는 빈 배열.
JSON: {"foods":[{"n":string,"amount":string,"k":number,"c":number,"p":number,"f":number,"sugar":number,"fiber":number,"na":number}],"total":{"kcal":number,"carbs":number,"protein":number,"fat":number,"sugar":number,"fiber":number,"sodium":number},"gl":"낮음"|"보통"|"높음","score":number,"good":[string],"improve":[string],"feedback":string,"confidence":string}`;
async function runMealAI(mid,date,k){const s=md(mid).meals[date]?.slots?.[k];if(!s?.photo)return;const plan=activePlan(md(mid));const label=SLOTS.find(x=>x[0]===k)[1];
 const r=await ai(NUTRI_PROMPT(label,plan),{files:[s.photo],tier:'quick',kind:'meal'});if(!r||typeof r!=='object')throw new Error('분석 결과를 받지 못했어요. 다시 시도해주세요.');
 const foods=(Array.isArray(r.foods)?r.foods:[]).map(f=>({n:String(f.n||'음식'),amount:String(f.amount||''),k:+f.k||0,c:+f.c||0,p:+f.p||0,f:+f.f||0,sugar:+f.sugar||0,fiber:+f.fiber||0,na:+f.na||0}));
 const sum=key=>foods.reduce((a,f)=>a+(+f[key]||0),0);const t=r.total||{};
 const total={kcal:+t.kcal||sum('k'),carbs:+t.carbs||sum('c'),protein:+t.protein||sum('p'),fat:+t.fat||sum('f'),sugar:+t.sugar||sum('sugar'),fiber:+t.fiber||sum('fiber'),sodium:+t.sodium||sum('na')};
 const patch={ai:{v:2,foods,total,gl:r.gl||'',score:+r.score||0,good:(r.good||[]).slice(0,3),improve:(r.improve||[]).slice(0,3),feedback:String(r.feedback||''),confidence:String(r.confidence||''),at:Date.now(),photo:s.photo}};
 const cur=md(mid).meals[date]?.slots?.[k]||{};if(!(cur.foods||[]).length||(cur.foods||[]).every(f=>f.ai))patch.foods=foods.map(f=>({n:f.n,sv:f.amount||'AI 추정',k:f.k,c:f.c,p:f.p,f:f.f,q:1,ai:1}));
 await saveSlot(mid,date,k,patch)}
function mealAIModal(){const {m:mid,d:date,s:k}=S.mv||{};const s=md(mid).meals[date]?.slots?.[k]||{};const A2=s.ai||{};const T=A2.total;const l=SLOTS.find(x=>x[0]===k)?.[1]||'';const bk=`ml_${mid}_${date}_${k}`;const running=S.busy['ai'+bk];
 const stale=A2.photo&&A2.photo!==s.photo;
 if(!T||A2.v!==2||stale)return `${mh(`${l} 음식 분석`)}${s.photo?`<img class="mvph" src="${fileUrl(s.photo)}" alt="${l} 사진">`:''}<div class="phe" style="aspect-ratio:auto;padding:26px">${running?'<span class="spin"></span>사진 속 음식을 분석하고 있어요…':S.mvErr?`<span class="err">${esc(S.mvErr)}</span><button class="btn sm pri" data-a="mealReAI">다시 분석</button>`:'<span class="spin"></span>분석을 준비하고 있어요…'}</div>`;
 const kc=[['탄수화물',T.carbs,4,'#4F5BFF'],['단백질',T.protein,4,'#16A37A'],['지방',T.fat,9,'#E07A2F']];const ks=kc.reduce((a,[,g,m])=>a+g*m,0)||1;
 const lvl=(v,lo,hi)=>v>=hi?'<span class="chip r xs">높음</span>':v<=lo?'<span class="chip g xs">낮음</span>':'<span class="chip xs">보통</span>';
 return `${mh(`${l} 음식 분석`)}<img class="mvph" src="${fileUrl(s.photo)}" alt="${l} 사진">
 <div class="row sb"><div><span class="big num">${Math.round(T.kcal)}</span><span class="muted"> kcal</span></div><div style="text-align:right">${A2.score?`<div style="color:#F5A524;font-size:18px">${'★'.repeat(Math.max(0,Math.min(5,A2.score)))}<span style="opacity:.25">${'★'.repeat(5-Math.max(0,Math.min(5,A2.score)))}</span></div>`:''}<div class="xs muted">사진 기반 추정 · 정확도 ${esc(A2.confidence||'보통')}</div></div></div>
 <div class="mbar" aria-hidden="true">${kc.map(([,g,m,c])=>`<i style="width:${g*m/ks*100}%;background:${c}"></i>`).join('')}</div>
 <div class="g3">${kc.map(([n,g,m,c])=>`<div class="stat"><div class="l"><span class="dot" style="background:${c}"></span>${n}</div><div class="v num">${Math.round(g)}<small class="xs">g</small></div><div class="xs muted num">${Math.round(g*m)}kcal · ${Math.round(g*m/ks*100)}%</div></div>`).join('')}</div>
 <div class="g3">${[['당류',T.sugar,'g',lvl(T.sugar,10,25)],['식이섬유',T.fiber,'g',T.fiber>=8?'<span class="chip g xs">충분</span>':T.fiber<3?'<span class="chip r xs">부족</span>':'<span class="chip xs">보통</span>'],['나트륨',T.sodium,'mg',lvl(T.sodium,600,1500)]].map(([n,v,u,c])=>`<div class="stat"><div class="l">${n}</div><div class="v num">${Math.round(v||0)}<small class="xs">${u}</small></div><div>${c}</div></div>`).join('')}</div>
 ${A2.gl?`<p class="sm">혈당 부담 예상: <b>${esc(A2.gl)}</b></p>`:''}
 <div class="card flat"><h3 class="sm">음식별 분석</h3><table class="tbl"><tr><th>음식</th><th>kcal</th><th>탄</th><th>단</th><th>지</th><th>당</th></tr>${(A2.foods||[]).map(f=>`<tr><td>${esc(f.n)}${f.amount?`<div class="xs muted">${esc(f.amount)}</div>`:''}</td><td class="num">${Math.round(f.k)}</td><td class="num">${Math.round(f.c)}</td><td class="num">${Math.round(f.p)}</td><td class="num">${Math.round(f.f)}</td><td class="num">${Math.round(f.sugar)}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">음식을 찾지 못했어요</td></tr>'}</table></div>
 ${A2.feedback?`<div class="note">${esc(A2.feedback)}</div>`:''}
 ${(A2.good||[]).length?`<div><b class="sm">잘한 점</b><ul class="ul">${A2.good.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}
 ${(A2.improve||[]).length?`<div><b class="sm">이렇게 바꿔보세요</b><ul class="ul">${A2.improve.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}
 <p class="xs muted">사진으로 추정한 값이라 실제와 다를 수 있어요. 질환이 있거나 약을 복용 중이면 전문가와 상의하세요.</p>
 <button class="btn ghost full" data-a="mealReAI" ${dis('ai'+bk)}>${bz('ai'+bk,ic('refresh',15)+' 다시 분석','분석 중…')}</button>`}
mealAIModal.live=true;
A.mealView=d=>{S.mv={m:d.m,d:d.d,s:d.s};S.mvErr='';openModal(mealAIModal);const s=md(d.m).meals[d.d]?.slots?.[d.s]||{};const A2=s.ai||{};if(!A2.total||A2.v!==2||(A2.photo&&A2.photo!==s.photo))A.mealReAI()};
A.mealReAI=()=>{const {m,d,s}=S.mv||{};if(!m)return;const bk=`ml_${m}_${d}_${s}`;S.mvErr='';return busy('ai'+bk,async()=>{try{await runMealAI(m,d,s)}catch(e){S.mvErr=e.message||'분석하지 못했어요.';throw e}finally{if(S.modal)renderModal()}})};
A.dietDay=({v})=>{S.dietDate=addDays(S.dietDate||today(),+v);render()};A.dietGo=({d})=>{S.dietDate=d;render()};
async function saveSlot(mid,date,k,patch,log){const cur=md(mid).meals[date];const slots={...(cur?.slots||{})};slots[k]={...(slots[k]||{}),...patch,at:Date.now()};await put('meals',`${mid}_${date}`,{...cur,memberId:mid,date,slots},log)}
A.mealPhoto=(d,files)=>busy(`ml_${d.m}_${d.d}_${d.s}`,async()=>{const r=await upload(files[0]);if(!r.type.startsWith('image'))throw new Error('사진 파일을 올려주세요.');const l=SLOTS.find(x=>x[0]===d.s)[1];await saveSlot(d.m,d.d,d.s,{photo:r.id},logo('meal',`${nm(d.m)} ${l} 식단 사진 업로드`));toast(`${l} 기록 완료! +10P 🎉`);const bk=`ml_${d.m}_${d.d}_${d.s}`;if(!(S.aiLeft&&!S.aiLeft.admin&&S.aiLeft.meal<=0))busy('ai'+bk,()=>runMealAI(d.m,d.d,d.s)).catch(()=>{})});
A.mealAI=d=>busy(`aiml_${d.m}_${d.d}_${d.s}`,async()=>{const s=md(d.m).meals[d.d]?.slots?.[d.s];if(!s?.photo)return;const plan=activePlan(md(d.m));
 const r=await ai(`이 사진은 회원의 ${SLOTS.find(x=>x[0]===d.s)[1]} 식사다. 음식을 알아보고 1인분 기준 칼로리를 추정하라.${plan?` 회원 목표: 하루 ${plan.kcal||'?'}kcal, 규칙: ${(plan.rules||[]).slice(0,5).join(' / ')}`:''} score(1~5)는 목표에 얼마나 맞는지, feedback은 칭찬 위주 1~2문장 한국어.
JSON: {"foods":[{"n":string,"k":number,"c":number,"p":number,"f":number}],"score":number,"feedback":string}`,{files:[s.photo]});
 const patch={ai:{score:r.score,feedback:r.feedback}};if(!(s.foods||[]).length&&Array.isArray(r.foods))patch.foods=r.foods.map(f=>({n:String(f.n||'음식'),sv:'AI 추정',k:+f.k||0,c:+f.c||0,p:+f.p||0,f:+f.f||0,q:1,ai:1}));await saveSlot(d.m,d.d,d.s,patch)});
const _bz=bz;
A.foodDel=async d=>{const s=md(d.m).meals[d.d]?.slots?.[d.s]||{};const foods=[...(s.foods||[])];foods.splice(+d.i,1);await saveSlot(d.m,d.d,d.s,{foods})};
A.mealLike=async d=>{const cur=md(d.m).meals[d.d];if(!cur)return;const review={...(cur.review||{})};review[d.s]={...(review[d.s]||{}),ok:!review[d.s]?.ok,at:Date.now()};await put('meals',cur.id,{...cur,review})};
A.mealCmt=async d=>{const cur=md(d.m).meals[d.d];if(!cur)return toast('기록이 있는 식사에만 코멘트할 수 있어요');const bk=`ml_${d.m}_${d.d}_${d.s}`;const review={...(cur.review||{})};review[d.s]={...(review[d.s]||{}),comment:S.f['rv_'+bk]||'',at:Date.now()};await put('meals',cur.id,{...cur,review});toast('코멘트를 남겼어요')};
// ---- 칼로리 검색 ----
const allFoods=()=>[...S.foods.map(f=>({...f,custom:1})),...FOODS];
const recentFoods=mid=>{const seen=new Set(),o=[];Object.values(md(mid).meals).sort((a,b)=>b.date.localeCompare(a.date)).forEach(m=>SLOTS.forEach(([k])=>(m.slots?.[k]?.foods||[]).forEach(f=>{if(!seen.has(f.n)&&!f.ai&&o.length<8){seen.add(f.n);o.push(f.n)}})));return o};
const fnorm=s=>String(s||'').toLowerCase().replace(/[\s()·,.\-]/g,'');
function foodMatch(q){const nq=fnorm(q);if(!nq)return [];const sc=[];for(const f of allFoods()){const n=fnorm(f.n);let s=n===nq?0:n.startsWith(nq)?1:n.includes(nq)?2:fnorm(f.g).includes(nq)?4:-1;if(s<0){const toks=q.trim().toLowerCase().split(/\s+/).filter(Boolean);if(toks.length>1&&toks.every(t=>n.includes(fnorm(t))))s=3}if(s>=0)sc.push([s,n.length,f])}return sc.sort((a,b)=>a[0]-b[0]||a[1]-b[1]).map(x=>x[2]).slice(0,60)}
A.fcat=({v,ctx})=>{S.f.fcat=S.f.fcat===v?'':v;if(ctx==='modal')renderModal();else render()};
function foodResults(q,ctx){q=q.trim();const all=allFoods();const fc=S.f.fcat||'';const cats=[...(S.foods.length?['추가 음식']:[]),...FOODCATS];
 const r=q?foodMatch(q):fc?all.filter(f=>fc==='추가 음식'?f.custom:f.g===fc):[];
 const catRow=q?'':`<p class="xs muted" style="margin:8px 0 4px">음식 ${all.length}개 · 분류로 찾아보기</p><div class="pills wrap">${cats.map(c=>`<button class="pill ${fc===c?'on':''}" data-a="fcat" data-v="${esc(c)}" data-ctx="${ctx}">${esc(c)}</button>`).join('')}</div>`;
 if(!q&&!fc)return catRow;
 return catRow+(r.length?r.map(f=>`<div class="frow"><div><b>${esc(f.n)}</b> ${f.custom?'<span class="chip p xs">추가 음식</span>':''}<div class="xs muted">${esc(f.sv)} · 탄 ${f.c}g · 단 ${f.p}g · 지 ${f.f}g</div></div><div class="kc num">${Math.round(f.k)}<small>kcal</small></div><button class="btn sm soft" data-a="foodAdd" data-n="${esc(f.n)}" data-ctx="${ctx}">추가</button></div>`).join(''):'<p class="empty">검색 결과가 없어요.</p>')
 +(q?`<div class="row" style="margin-top:10px"><button class="btn ghost" style="flex:1" data-a="foodAI" data-q="${esc(q)}" data-ctx="${ctx}" ${dis('fai')}>${bz('fai',ic('spark',16)+' AI로 칼로리 추정','AI 추정 중…')}</button><button class="btn ghost" style="flex:1" data-a="foodManual" data-q="${esc(q)}">직접 입력</button></div>`:'')}
PART.foodPage=()=>foodResults(S.f.fq||'','page');PART.foodModal=()=>foodResults(S.f.fqm||'','modal');
const qtySeg=()=>`<div class="row nw"><span class="sm muted b">양</span><div class="seg" style="flex:1">${['0.5','1','1.5','2'].map(q=>`<button class="${(S.f.fqty||'1')===q?'on':''}" data-a="fqty" data-v="${q}">${q}인분</button>`).join('')}</div></div>`;
A.fqty=({v})=>{S.f.fqty=v;render();renderModal()};
function foodSearchSec(mid){const sl=S.f.fslot||guessSlot();const rc=recentFoods(mid);return `<div class="card"><div class="row nw"><input class="inp" placeholder="음식 검색 (예: 닭가슴살, 김치찌개)" data-f="fq" data-live="foodPage" value="${esc(fv('fq'))}"></div>
 ${rc.length?`<div class="pills">${rc.map(n=>`<button class="pill" data-a="foodAdd" data-n="${esc(n)}" data-ctx="page">+ ${esc(n)}</button>`).join('')}</div>`:''}
 <div class="seg">${SLOTS.map(([k,l])=>`<button class="${sl===k?'on':''}" data-a="fslot" data-v="${k}">${l}</button>`).join('')}</div>${qtySeg()}<p class="xs muted">'추가'를 누르면 오늘 ${SLOTS.find(x=>x[0]===sl)[1]}에 담겨요. 칼로리는 일반적인 1인분 기준 대략치예요.</p><div id="p-foodPage">${PART.foodPage()}</div></div>`}
A.fslot=({v})=>{S.f.fslot=v;render()};
A.foodPick=d=>{S.foodCtx={m:d.m,d:d.d,s:d.s};S.f.fqm='';S.f.fqty='1';openModal(()=>`${mh(`${SLOTS.find(x=>x[0]===S.foodCtx.s)[1]}에 음식 추가`)}<input class="inp" placeholder="음식 검색" data-f="fqm" data-live="foodModal" value="${esc(fv('fqm'))}">${qtySeg()}<div id="p-foodModal">${PART.foodModal()}</div>`)};
A.foodAdd=async({n,ctx})=>{const f=allFoods().find(x=>x.n===n);if(!f)return;const q=+(S.f.fqty||1);const c=ctx==='modal'?S.foodCtx:{m:me().id,d:today(),s:S.f.fslot||guessSlot()};const s=md(c.m).meals[c.d]?.slots?.[c.s]||{};
 await saveSlot(c.m,c.d,c.s,{foods:[...(s.foods||[]),{n:f.n,sv:f.sv,k:f.k*q,c:n1(f.c*q),p:n1(f.p*q),f:n1(f.f*q),q}]},!(s.foods||[]).length&&!s.photo?logo('meal',`${nm(c.m)} ${SLOTS.find(x=>x[0]===c.s)[1]} 식단 기록`):null);toast(`${f.n} 추가 (${Math.round(f.k*q)}kcal)`);if(ctx==='modal')closeModal()};
A.foodAI=({q,ctx})=>busy('fai',async()=>{const r=await ai(`음식 "${q}" 1인분(한국 일반 제공량)의 영양 정보를 추정하라. JSON: {"n":"정확한 음식 이름","sv":"제공량 예: 1그릇(400g)","k":kcal숫자,"c":탄수화물g,"p":단백질g,"f":지방g}`,{tier:'quick'});if(!r||!r.n)throw new Error('추정하지 못했어요.');
 const f={n:String(r.n),sv:String(r.sv||'1인분')+' · AI추정',k:Math.round(+r.k||0),c:n1(r.c),p:n1(r.p),f:n1(r.f),createdAt:Date.now()};if(!allFoods().some(x=>x.n===f.n))await put('foods',uid(),f);if(ctx==='modal')S.f.fqm=f.n;else S.f.fq=f.n;toast(`'${f.n}' ${f.k}kcal — 음식 목록에 추가했어요`)});
A.foodManual=({q})=>{clearF('fm_');S.f.fm_n=q;const back=S.modal;openModal(()=>`${mh('음식 직접 입력')}<div><label class="fl">음식 이름</label><input class="inp" data-f="fm_n" value="${esc(fv('fm_n'))}"></div><div><label class="fl">제공량</label><input class="inp" data-f="fm_sv" placeholder="예: 1그릇(300g)" value="${esc(fv('fm_sv'))}"></div><div class="fg">${[['k','칼로리(kcal)'],['c','탄수화물(g)'],['p','단백질(g)'],['f','지방(g)']].map(([k,l])=>`<div><label class="fl">${l}</label><input class="inp" type="number" inputmode="decimal" data-f="fm_${k}" value="${esc(fv('fm_'+k))}"></div>`).join('')}</div><button class="btn pri lg full" data-a="foodManualSave">음식 목록에 추가</button><p class="xs muted">추가한 음식은 모든 회원이 검색할 수 있어요.</p>`)};
A.foodManualSave=async()=>{const n=(S.f.fm_n||'').trim();if(!n||!S.f.fm_k)return toast('이름과 칼로리를 입력해주세요');await put('foods',uid(),{n,sv:S.f.fm_sv||'1인분',k:+S.f.fm_k||0,c:+S.f.fm_c||0,p:+S.f.fm_p||0,f:+S.f.fm_f||0,createdAt:Date.now()});S.f.fq=n;clearF('fm_');closeModal();toast('음식을 추가했어요. 이제 검색해서 담을 수 있어요')};
// ---- 식단표 ----
function planMeals(meals,times,pk){const mk=(k,l,e)=>{const a=meals?.[k]||[];if(!a.length)return '';const tot=a.reduce((x,y)=>x+(+y.kcal||0),0);
 return `<div class="sec"><div class="row sb"><h4>${e} ${l}${times?.[k]?` <span class="xs muted">${esc(times[k])}</span>`:''}</h4>${tot?`<span class="xs b num">${Math.round(tot)} kcal</span>`:''}</div><div class="plist">${a.map(x=>`<div class="pit"><div class="grow"><b>${esc(x.food||x.n||x)}</b>${x.amount?` <span class="sm">· ${esc(x.amount)}</span>`:''}${x.note?`<div class="xs muted">${esc(x.note)}</div>`:''}</div>${+x.kcal?`<span class="xs num muted">${x.est?'약 ':''}${Math.round(x.kcal)}kcal</span>`:''}</div>`).join('')}</div></div>`};
 return SLOTS.map(([k,l,e])=>mk(k,l,e)).join('')}
function planHTML(p,label,pk){if(!p)return '';const days=Array.isArray(p.days)?p.days.filter(d=>d&&d.meals):[];const di=Math.min(days.length-1,Math.max(0,+(S.f['pday_'+(pk||label)]||0)));
 return `<div class="card"><div class="row sb"><h2>${esc(p.title||label)}</h2><span class="chip p">${label}</span></div>
 ${p.summary?`<p class="sm">${esc(p.summary)}</p>`:''}
 ${p.kcal||p.carbs||p.protein?`<div class="kv">${p.kcal?`<div><span>하루 목표</span><b>${esc(p.kcal)}<small class="xs"> kcal</small></b></div>`:''}${p.carbs?`<div><span>탄수화물</span><b>${esc(p.carbs)}</b></div>`:''}${p.protein?`<div><span>단백질</span><b>${esc(p.protein)}</b></div>`:''}${p.fat?`<div><span>지방</span><b>${esc(p.fat)}</b></div>`:''}${p.water?`<div><span>물</span><b>${esc(p.water)}</b></div>`:''}</div>`:''}
 ${p.rationale?`<p class="sm">${esc(p.rationale)}</p>`:''}
 ${days.length>1?`<div class="pills">${days.map((d,i)=>`<button class="pill ${i===di?'on':''}" data-a="pDay" data-k="${esc(pk||label)}" data-v="${i}">${esc(d.label||`${i+1}일차`)}</button>`).join('')}</div>${planMeals(days[di].meals,days[di].times||p.times)}${days[di].note?`<p class="xs muted">${esc(days[di].note)}</p>`:''}`:planMeals(days.length===1?days[0].meals:p.meals,p.times)}
 ${(p.sections||[]).filter(x=>x&&(x.items||[]).length).map(x=>`<div class="sec"><h4>📌 ${esc(x.title||'')}</h4>${ul(x.items)}</div>`).join('')}
 ${p.rules?.length?`<div class="sec"><h4>✅ 지켜야 할 규칙</h4>${ul(p.rules)}</div>`:''}${p.avoid?.length?`<div class="sec"><h4>🚫 피해야 할 음식</h4>${ul(p.avoid)}</div>`:''}${p.swaps?.length?`<div class="sec"><h4>🔁 바꿔 먹어도 돼요</h4>${ul(p.swaps)}</div>`:''}${p.tips?.length?`<div class="sec"><h4>💡 팁</h4>${ul(p.tips)}</div>`:''}${p.memo?`<div class="note" style="white-space:pre-wrap">📝 트레이너 메모 · ${esc(p.memo)}</div>`:''}</div>`}
A.pDay=({k,v})=>{S.f['pday_'+k]=v;render();renderModal()};
function dietPlanView(mid){const D=md(mid).diet||{};if(!D.plan&&!D.aiPlan)return '<div class="card"><p class="empty">아직 식단표가 없어요.<br>트레이너가 식단표를 올리거나, AI 식단 탭에서 만들 수 있어요.</p></div>';
 return `${planHTML(D.plan,'트레이너 식단')}${srcBox(D)}${planHTML(D.aiPlan,'AI 추천 식단')}`}
function dietPlanAdmin(mid){const D=md(mid).diet||{};return `<div class="card"><h3>식단표 업로드</h3><p class="sm muted">Word(.docx), PDF, 사진·스캔본(JPG·PNG)을 올리면 AI가 아침·점심·저녁·간식, 목표 칼로리, 규칙으로 깔끔하게 정리해서 회원과 함께 볼 수 있어요.</p>
 <label class="btn grad lg full">${S.busy.dietup?'<span class="spin"></span> 문서를 읽고 정리하는 중… (최대 1분)':ic('up',18)+' 파일 선택'}<input type="file" hidden accept=".docx,.pdf,.txt,image/*" data-file="dietUp" data-m="${mid}" ${dis('dietup')}></label></div>
 ${D.plan?`${planHTML(D.plan,'트레이너 식단')}${srcBox(D)}<div class="card"><h3>트레이너 메모 (회원에게 표시)</h3><textarea class="inp" data-f="dmemo_${mid}">${esc(fv('dmemo_'+mid,D.plan.memo||''))}</textarea><div class="row"><button class="btn pri" style="flex:1" data-a="dietMemo" data-m="${mid}">메모 저장</button><button class="btn ghost dng" data-a="dietClear" data-m="${mid}">식단표 삭제</button></div></div>`:''}`}
A.dietUp=(d,files)=>busy('dietup',async()=>{const f=files[0];const mid=d.m;const n=(f.name||'').toLowerCase();let text='',fileId=null;
 if(n.endsWith('.docx'))text=await docxText(f);else if(n.endsWith('.doc'))throw new Error('구버전 .doc 파일은 Word에서 .docx로 저장 후 올려주세요.');else if(n.endsWith('.txt'))text=await f.text();
 else if(n.endsWith('.pdf')||(f.type||'').startsWith('image/')){fileId=(await upload(f,2200)).id}else throw new Error('Word(.docx), PDF, 이미지, 텍스트 파일만 올릴 수 있어요.');
 const plan=await ai(`다음은 트레이너가 회원에게 준 식단 문서${fileId?'(첨부 파일)':''}다. 회원이 휴대폰에서 한눈에 보기 쉽게 정리하라.
규칙: 문서에 있는 음식·양·시간·규칙만 옮기고 새 음식을 지어내지 마라. 표가 '|'로 나뉘어 있으면 표로 읽어라. 요일·일차별로 식단이 다르면 days에 나눠 담고(label 예: "월요일","1일차"), 매일 같으면 meals만 채워라. 끼니 이름이 다르면 가장 가까운 끼니로(아침/점심/저녁/간식, 운동 전후 식사는 간식). 각 음식의 kcal은 문서에 있으면 그 값(est:false), 없으면 일반적인 1인분 기준으로 추정(est:true). times는 끼니 시간이 문서에 있을 때만. 끼니에 안 맞는 내용(보충제, 물, 주의사항 등)은 sections로. summary는 이 식단의 핵심을 2문장으로. 없는 값은 null 또는 빈 배열. 한국어.
${text?`[문서 내용]\n${text.slice(0,30000)}`:''}
JSON: {"title":string,"summary":string,"kcal":number|null,"carbs":string|null,"protein":string|null,"fat":string|null,"water":string|null,"times":{"breakfast":string|null,"lunch":string|null,"dinner":string|null,"snack":string|null},"meals":{"breakfast":[{"food":string,"amount":string,"note":string,"kcal":number|null,"est":boolean}],"lunch":[],"dinner":[],"snack":[]},"days":[{"label":string,"meals":{"breakfast":[],"lunch":[],"dinner":[],"snack":[]},"note":string}],"sections":[{"title":string,"items":[string]}],"rules":[string],"avoid":[string],"swaps":[string],"tips":[string]}`,{files:fileId?[fileId]:[]});
 if(!plan||(!plan.meals&&!(plan.days||[]).length))throw new Error('식단 내용을 정리하지 못했어요. 더 선명한 파일로 시도해주세요.');const cur=md(mid).diet||{};
 await put('diets',mid,{...cur,memberId:mid,plan:{...plan,memo:cur.plan?.memo||''},source:{name:f.name,fileId,text:text?text.slice(0,20000):''},planAt:Date.now()},logo('diet',`${nm(mid)} 식단표 등록 (${f.name})`));toast('식단표를 정리해서 등록했어요')});
A.dietMemo=async({m:mid})=>{const D=md(mid).diet;await put('diets',mid,{...D,plan:{...D.plan,memo:S.f['dmemo_'+mid]??D.plan.memo}});toast('메모를 저장했어요')};
A.dietClear=async({m:mid})=>{if(!await ask('트레이너 식단표를 삭제할까요?','','삭제',true))return;const D=md(mid).diet;await put('diets',mid,{...D,plan:null,source:null})};
// ---- 신체 정보 & AI 식단 ----
const PFK=['sex','age','h','w','fat','mus','bmr','act','goal','nmeal','disease','allergy','pref'];
function profileForm(mid){const p=S.members[mid]?.profile||{};const i=(k,l,u='',t='number',ph='')=>`<div><label class="fl">${l}${u?` (${u})`:''}</label><input class="inp" type="${t}" ${t==='number'?'inputmode="decimal"':''} placeholder="${ph}" data-f="${fk(mid,'pf_'+k)}" value="${esc(fv(fk(mid,'pf_'+k),p[k]??''))}"></div>`;const s=(k,l,a)=>`<div><label class="fl">${l}</label><select class="inp" data-f="${fk(mid,'pf_'+k)}">${a.map(o=>`<option ${fv(fk(mid,'pf_'+k),p[k]||a[0])===o?'selected':''}>${o}</option>`).join('')}</select></div>`;
 return `<div class="fg">${s('sex','성별',['남','여'])}${i('age','나이','세')}${i('h','키','cm')}${i('w','몸무게','kg')}${i('fat','체지방률','%')}${i('mus','골격근량','kg')}${i('bmr','기초대사량','kcal')}${s('act','활동량',['적음(앉아서 일함)','보통','많음(서서/움직이는 일)'])}${s('goal','목표',['체지방 감량','근육량 증가','체중 유지·건강','체중 증가'])}${s('nmeal','하루 끼니',['3끼+간식','3끼','2끼','5~6끼 소분'])}</div>
 ${i('disease','질환·복용약','','text','예: 고혈압, 당뇨, 없음')}${i('allergy','알레르기·못 먹는 음식','','text')}${i('pref','좋아하는 음식 / 생활 패턴','','text','예: 점심은 회사 구내식당')}<p class="xs muted">인바디를 올리면 몸무게·체지방률·골격근량·기초대사량이 자동으로 채워져요.</p>`}
function readProfile(mid){const p=S.members[mid]?.profile||{};const o={};PFK.forEach(k=>o[k]=fv(fk(mid,'pf_'+k),p[k]??''));return o}
A.saveProfile=async({m:mid})=>{await act('profile',{memberId:mid,profile:readProfile(mid)});toast('신체 정보를 저장했어요')};
function dietAI(mid){const D=md(mid).diet||{};return `<div class="card"><h3>내 신체 정보</h3>${profileForm(mid)}<div class="row"><button class="btn" data-a="saveProfile" data-m="${mid}">정보 저장</button><button class="btn grad" style="flex:1" data-a="genDiet" data-m="${mid}" ${dis('gd'+mid)}>${bz('gd'+mid,ic('spark',16)+' AI 식단 만들기'+aiLeftTxt('diet'),'AI가 식단을 구성 중…')}</button></div></div>
 ${D.aiPlan?planHTML(D.aiPlan,'AI 추천 식단'):''}<p class="xs muted">AI 식단은 일반적인 참고용이에요. 질환이 있거나 약을 복용 중이면 의사·트레이너와 상의해주세요.</p>`}
A.genDiet=({m:mid})=>busy('gd'+mid,async()=>{const p=readProfile(mid);await act('profile',{memberId:mid,profile:p});const ib=md(mid).inbody[0];const tp=md(mid).diet?.plan;
 const r=await ai(`너는 스포츠 영양사다. 아래 회원 정보로 한국에서 쉽게 구할 수 있는 음식으로 하루 식단을 구성하라.
[회원] 성별:${p.sex} 나이:${p.age||'-'} 키:${p.h||'-'}cm 체중:${p.w||'-'}kg 체지방률:${p.fat||'-'}% 골격근량:${p.mus||'-'}kg 기초대사량:${p.bmr||'-'}kcal 활동량:${p.act} 목표:${p.goal} 끼니:${p.nmeal}
질환/약:${p.disease||'없음'} 알레르기/못 먹는 음식:${p.allergy||'없음'} 생활/선호:${p.pref||'-'}
${ib?`[최근 인바디 ${ib.date}] ${JSON.stringify(ib.metrics||{})}`:''}${tp?`\n[트레이너 식단 규칙 — 반드시 존중] ${(tp.rules||[]).join(' / ')}`:''}
기초대사량·활동량·목표로 하루 칼로리와 탄단지(g)를 계산하고 근거(rationale) 2문장. 질환이 있으면 맞게 조절. 각 음식에 양(g/개). 한국어.
JSON: {"title":string,"kcal":number,"carbs":"000g","protein":"000g","fat":"00g","rationale":string,"meals":{"breakfast":[{"food":string,"amount":string,"note":string}],"lunch":[],"dinner":[],"snack":[]},"rules":[string],"avoid":[string],"tips":[string]}`,{kind:'diet'});
 if(!r||!r.meals)throw new Error('식단을 만들지 못했어요. 다시 시도해주세요.');await put('diets',mid,{...(md(mid).diet||{}),memberId:mid,aiPlan:r,aiAt:Date.now()},logo('diet',`${nm(mid)} AI 식단 생성 (${r.kcal||'?'}kcal)`));toast('AI 식단이 준비됐어요')});

// ================= 예약 =================
function slotsFor(){const st=S.settings||{};const [oh,om]=(st.open||'06:00').split(':').map(Number);const [ch,cm]=(st.close||'22:00').split(':').map(Number);const step=Math.max(10,+st.slotMin||60);const o=[];for(let t=oh*60+om;t+step<=ch*60+cm;t+=step)o.push(`${pad(Math.floor(t/60))}:${pad(t%60)}`);return o}
const dayClosed=date=>(S.settings?.closedDays||[]).includes(parseD(date).getDay())||!!S.blocks[date+'_all'];
function slotState(date,time,mid){const id=sid(date,time);const b=S.bookingMap[id];if(b)return {s:b.memberId===mid?'mine':'taken',b};if(S.blocks[id]||dayClosed(date))return {s:'blocked'};if(slotDT(date,time)<=new Date())return {s:'past'};return {s:'open'}}
const cancelH=()=>+(S.settings?.cancelHours??6);
const canModify=b=>slotDT(b.date,b.time)-Date.now()>=cancelH()*3600000;
function calHTML(act,sel,mark,disFn){if(!S.cal){const n=new Date();S.cal={y:n.getFullYear(),m:n.getMonth()}}const {y,m}=S.cal;const f=new Date(y,m,1).getDay(),n=new Date(y,m+1,0).getDate();let c='';for(let i=0;i<f;i++)c+='<span></span>';
 for(let d=1;d<=n;d++){const dt=`${y}-${pad(m+1)}-${pad(d)}`;const di=disFn?disFn(dt):false;const w=new Date(y,m,d).getDay();c+=`<button class="cd ${dt===sel?'sel':''} ${dt===today()?'td':''} ${di?'dis':''} ${w===0?'sun':w===6?'sat':''}" ${di?'disabled':''} data-a="${act}" data-d="${dt}"><span>${d}</span>${mark?mark(dt):''}</button>`}
 return `<div class="cal"><div class="calh"><button class="ib sm" data-a="calMove" data-v="-1">${ic('left')}</button><b class="num">${y}년 ${m+1}월</b><button class="ib sm" data-a="calMove" data-v="1">${ic('right')}</button></div><div class="calw">${DOW.map(x=>`<span>${x}</span>`).join('')}</div><div class="calg">${c}</div></div>`}
A.calMove=({v})=>{const c=S.cal;const d=new Date(c.y,c.m+(+v),1);S.cal={y:d.getFullYear(),m:d.getMonth()};render()};
function vMBook(){const m=me();const cur=subOf('book','new');const fut=futureOf(m.id);return `${seg('book',[['new','예약하기'],['mine',`내 예약${fut.length?` ${fut.length}`:''}`]],'new')}${cur==='mine'?myBookings(m):newBooking(m)}`}
function newBooking(m){const bk=S.bk;const chg=bk.changeFrom&&S.bookingMap[bk.changeFrom];const maxD=addDays(today(),60);const rv=reservable(m);const type=chg?chg.type:(bk.type||'lesson');
 return `${chg?`<div class="note w">🔁 <b>예약 변경 중</b> · 기존 ${fmtD(chg.date)} ${chg.time} ${typeName(chg.type)} → 새 날짜와 시간을 골라주세요. <button class="btn sm" data-a="bkChangeCancel">변경 취소</button></div>`:`<div class="seg">${[['lesson','🏋️ PT 수업'],['consult','💬 PT 상담']].map(([v,l])=>`<button class="${type===v?'on':''}" data-a="bkType" data-v="${v}">${l}</button>`).join('')}</div>`}
 <div class="card"><div class="xs muted b">1. 날짜 선택</div>${calHTML('bkDate',bk.date,dt=>{const mine=S.bookings.some(b=>b.memberId===m.id&&b.date===dt);return `<span class="mk">${mine?'<i></i>':''}</span>`},dt=>dt<today()||dt>maxD||dayClosed(dt))}</div>
 ${bk.date?`<div class="card"><div class="row sb"><div class="xs muted b">2. 시간 선택 · ${fmtD(bk.date)}</div><span class="xs muted">${S.settings.slotMin||60}분</span></div><div class="slots">${slotsFor().map(t=>{const st=slotState(bk.date,t,m.id);const lab={open:'예약 가능',taken:'마감',mine:'내 예약',blocked:'불가',past:'지남'}[st.s];return `<button class="slot ${bk.time===t?'on':''} ${st.s==='mine'?'mine':''}" ${st.s!=='open'?'disabled':''} data-a="bkTime" data-t="${t}">${t}<small>${lab}</small></button>`}).join('')}</div></div>`:''}
 ${bk.date&&bk.time?`<div class="card" id="bkconfirm"><div class="xs muted b">3. 예약 확인</div><div class="bk"><div class="t num">${bk.time}</div><div class="grow"><b>${fmtD(bk.date)}</b><div class="xs muted">${typeName(type)} · ${S.settings.slotMin||60}분</div></div></div>
 <input class="inp" placeholder="요청사항 (선택)" data-f="bk_memo" value="${esc(fv('bk_memo'))}">
 ${!chg&&type==='lesson'&&rv<=0?`<div class="note w">예약 가능한 잔여 수업이 없어요 (잔여 ${remaining(m)}회 중 ${remaining(m)-rv}회 예약됨). 트레이너에게 재등록을 문의하거나 상담을 예약해주세요.</div>`:''}
 <p class="xs muted">· 예약 시간 기준 ${cancelH()}시간 전부터는 변경·취소할 수 없어요.</p>
 <button class="btn grad lg full" data-a="bkConfirm" ${dis('bk')} ${!chg&&type==='lesson'&&rv<=0?'disabled':''}>${bz('bk',chg?'이 시간으로 변경하기':`${typeName(type)} 예약하기`)}</button></div>`:''}`}
A.bkDate=({d})=>{S.bk={...S.bk,date:d,time:null};render()};
A.bkTime=({t})=>{S.bk={...S.bk,time:t};render();setTimeout(()=>$('#bkconfirm')?.scrollIntoView({behavior:'smooth',block:'center'}),60)};
A.bkType=({v})=>{S.bk={...S.bk,type:v};render()};A.bkChangeCancel=()=>{S.bk={};render()};
A.bkConfirm=()=>busy('bk',async()=>{const {date,time,changeFrom}=S.bk;if(!date||!time)return;await act('book',{date,time,type:S.bk.type||'lesson',memo:S.f.bk_memo||'',changeFrom:changeFrom||undefined});toast(changeFrom?'예약을 변경했어요':'예약이 완료됐어요! 🎉');S.bk={};delete S.f.bk_memo;S.sub.book='mine'});
function myBookings(m){const fut=futureOf(m.id);const past=S.bookings.filter(b=>b.memberId===m.id&&!fut.includes(b)).sort(byDT).reverse().slice(0,10);const h=cancelH();
 return `<div class="card"><h3>다가오는 예약</h3>${fut.length?fut.map(b=>{const ok=canModify(b);const dd=Math.round((parseD(b.date)-parseD(today()))/864e5);return `<div class="bk"><div class="t num">${b.time}</div><div class="grow"><div class="row"><b>${fmtD(b.date)}</b><span class="dday">${dd?'D-'+dd:'D-DAY'}</span></div><span class="tag ${b.type==='consult'?'c':''}">${typeName(b.type)}</span>${b.memo?`<div class="xs muted">${esc(b.memo)}</div>`:''}${ok?'':`<div class="xs warn b">${h}시간 이내라 변경·취소 불가</div>`}</div><div class="col" style="gap:5px"><button class="btn sm soft" data-a="bkChange" data-id="${b.id}" ${ok?'':'disabled'}>변경</button><button class="btn sm ghost dng" data-a="bkCancel" data-id="${b.id}" ${ok?'':'disabled'}>취소</button></div></div>`}).join('<div style="height:8px"></div>'):'<p class="empty">다가오는 예약이 없어요.</p>'}
 <p class="xs muted">예약 ${h}시간 전부터는 앱에서 변경·취소가 막혀요. 급한 사정은 트레이너에게 직접 연락해주세요.</p></div>
 <div class="card"><h3>📅 내 휴대폰 캘린더에 연동</h3><p class="sm muted">아래 주소를 구독하면 예약·변경·취소가 휴대폰 캘린더에 자동으로 반영돼요.</p>${icsBox(m.icsToken)}</div>
 ${past.length?`<div class="card"><h3>지난 예약</h3><div class="list">${past.map(b=>`<div class="li"><div class="grow"><b class="num">${fmtD(b.date)} ${b.time}</b> <span class="xs muted">${typeName(b.type)}</span></div>${b.status==='done'?'<span class="tag d">완료</span>':b.status==='noshow'?'<span class="tag n">노쇼</span>':'<span class="xs muted">지남</span>'}</div>`).join('')}</div></div>`:''}`}
function icsBox(tok){if(!tok)return '';const url=`${API}/cal/${tok}.ics`;const wc=url.replace(/^https?:/,'webcal:');return `<div class="row nw"><input class="inp xs" readonly value="${esc(url)}"><button class="btn sm soft" data-a="copy" data-v="${esc(url)}">${ic('copy',14)} 복사</button></div><div class="row"><a class="btn sm" href="${esc(wc)}">아이폰·맥 캘린더에 추가</a><a class="btn sm" href="https://calendar.google.com/calendar/r?cid=${encodeURIComponent(wc)}" target="_blank" rel="noopener">구글 캘린더에 추가</a></div><p class="xs muted">네이버 캘린더: 캘린더 설정 → 구독 캘린더 추가 → 위 주소 붙여넣기. (구글은 반영까지 몇 시간 걸릴 수 있어요)</p>`}
A.copy=async({v})=>{try{await navigator.clipboard.writeText(v);toast('복사했어요')}catch(e){toast('주소를 길게 눌러 복사해주세요')}};
A.bkChange=({id})=>{const b=S.bookingMap[id];if(!b||!canModify(b))return toast('변경할 수 없는 예약이에요');S.bk={changeFrom:id};S.sub.book='new';const d=parseD(b.date);S.cal={y:d.getFullYear(),m:d.getMonth()};window.scrollTo(0,0);render()};
A.bkCancel=async({id})=>{const b=S.bookingMap[id];if(!b)return;if(!canModify(b))return toast(`예약 ${cancelH()}시간 전부터는 취소할 수 없어요`);if(!await ask('예약을 취소할까요?',`${fmtD(b.date)} ${b.time} ${typeName(b.type)}`,'예약 취소',true))return;await act('book/cancel',{id});toast('예약을 취소했어요')};

// ================= 영상 =================
function vcard(v,adm){const id=ytId(v.url);if(S.playV===v.id&&id)return `<div class="vcard">${ytEmbed(id)}<div class="vb row sb nw"><b class="sm">${esc(v.title)}</b><button class="btn sm ghost" data-a="vStop">닫기</button></div></div>`;
 return `<div class="vrow"><div class="vths" data-a="${id?'vPlay':'vOpen'}" data-id="${v.id}" data-u="${esc(v.url)}" style="background-image:${id?`url(https://i.ytimg.com/vi/${id}/mqdefault.jpg)`:VCOL[v.cat]}"><div class="pl">${ic('play',14)}</div></div><div class="grow" data-a="${id?'vPlay':'vOpen'}" data-id="${v.id}" data-u="${esc(v.url)}"><div class="sm b vtt">${esc(v.title)}</div>${v.desc?`<div class="xs muted ell">${esc(v.desc)}</div>`:''}</div>${adm?`<button class="btn sm ghost dng" data-a="vidDel" data-id="${v.id}">삭제</button>`:''}</div>`}
const VPP=10;
function vList(l,key,adm){if(!l.length)return '<p class="empty">아직 등록된 영상이 없어요.</p>';const pages=Math.ceil(l.length/VPP);const pg=Math.min(Math.max(1,S.vpage?.[key]||1),pages);
 const nums=[];for(let i=1;i<=pages;i++)if(i===1||i===pages||Math.abs(i-pg)<=2)nums.push(i);else if(nums[nums.length-1]!=='…')nums.push('…');
 return `<div class="vlist">${l.slice((pg-1)*VPP,pg*VPP).map(v=>vcard(v,adm)).join('')}</div>${pages>1?`<div class="pager"><button class="pgb" data-a="vPage" data-k="${key}" data-v="${pg-1}" ${pg<=1?'disabled':''}>‹</button>${nums.map(n=>n==='…'?'<span class="pgd">…</span>':`<button class="pgb ${n===pg?'on':''}" data-a="vPage" data-k="${key}" data-v="${n}">${n}</button>`).join('')}<button class="pgb" data-a="vPage" data-k="${key}" data-v="${pg+1}" ${pg>=pages?'disabled':''}>›</button></div><p class="xs muted" style="text-align:center">${l.length}편 중 ${(pg-1)*VPP+1}–${Math.min(pg*VPP,l.length)}</p>`:''}`}
A.vPage=({k,v})=>{S.vpage={...(S.vpage||{}),[k]:+v};S.playV=null;render();const el=document.querySelector('.vlist');if(el)el.scrollIntoView({block:'start',behavior:'smooth'})};
A.vStop=()=>{S.playV=null;render()};
A.vPlay=({id})=>{S.playV=id;render()};A.vOpen=({u})=>window.open(u,'_blank');
function vMVideo(){const cur=subOf('video','exercise');const opts=[...Object.entries(VC),['mine','📹 내 자세 피드백']];
 return `<div class="pills">${opts.map(([k,l])=>`<button class="pill ${cur===k?'on':''}" data-a="sub" data-k="video" data-v="${k}">${l}</button>`).join('')}</div>
 ${cur==='mine'?formVidSec(me().id,false):vList(S.videos.filter(v=>v.cat===cur),'m_'+cur)}`}
function formVidSec(mid,adm){const l=S.formvids.filter(v=>!mid||v.memberId===mid);
 return `${!adm?`<div class="card tint1"><h3>📹 운동 영상 올리고 피드백 받기</h3><p class="sm muted">혼자 운동하는 모습을 찍어 올리면 트레이너가 자세를 보고 코멘트해 드려요. (최대 50MB · 15~30초 권장)</p>
 <input class="inp" placeholder="제목 (예: 스쿼트 60kg 자세 봐주세요)" data-f="fv_title" value="${esc(fv('fv_title'))}"><input class="inp" placeholder="궁금한 점 (선택)" data-f="fv_note" value="${esc(fv('fv_note'))}">
 <label class="btn grad lg full">${S.busy.fv?'<span class="spin"></span> 업로드 중… 잠시만요':ic('up',18)+' 영상 선택해서 올리기'}<input type="file" hidden accept="video/*" data-file="fvUp" ${dis('fv')}></label></div>`:''}
 ${l.length?l.map(v=>fvCard(v,adm)).join(''):'<p class="empty">올라온 영상이 없어요.</p>'}`}
function fvCard(v,adm){const st=v.status==='reviewed'?'<span class="chip g">코멘트 완료</span>':'<span class="chip y">확인 대기</span>';const k='fc_'+v.id;
 return `<div class="card"><div class="row sb"><div><b>${esc(v.title||'운동 영상')}</b><div class="xs muted">${adm?esc(nm(v.memberId))+' · ':''}${ago(v.createdAt)}</div></div>${st}</div>
 <video src="${fileUrl(v.fileId)}" controls playsinline preload="metadata"></video>${v.note?`<div class="cmt"><b class="xs">회원</b><div class="sm">${esc(v.note)}</div></div>`:''}
 ${(v.comments||[]).map(c=>`<div class="cmt ${c.by==='admin'?'adm':''}"><div class="row sb"><b class="xs ${c.by==='admin'?'pc':''}">${c.by==='admin'?'트레이너':'회원'}</b><span class="xs muted">${ago(c.at)}</span></div><div class="sm" style="white-space:pre-wrap">${esc(c.text)}</div></div>`).join('')}
 <div class="row nw"><input class="inp" placeholder="${adm?'자세 피드백을 남겨주세요':'답글 남기기'}" data-f="${k}" value="${esc(fv(k))}"><button class="btn pri" data-a="fvCmt" data-id="${v.id}">등록</button></div>
 <button class="btn sm ghost dng" data-a="fvDel" data-id="${v.id}">영상 삭제</button></div>`}
A.fvUp=(d,files)=>busy('fv',async()=>{const r=await upload(files[0]);if(!r.type.startsWith('video'))throw new Error('영상 파일을 올려주세요.');const m=me();await put('formvids',uid(),{memberId:m.id,fileId:r.id,title:S.f.fv_title||'운동 영상',note:S.f.fv_note||'',comments:[],status:'new',createdAt:Date.now(),lastAt:Date.now()},logo('video',`${m.name} 자세 피드백 영상 업로드: ${S.f.fv_title||'운동 영상'}`));clearF('fv_');toast('영상을 올렸어요. 트레이너가 확인 후 코멘트해 드릴게요!')});
A.fvCmt=async({id})=>{const v=S.formvids.find(x=>x.id===id);const t=(S.f['fc_'+id]||'').trim();if(!v||!t)return;await put('formvids',id,{...v,comments:[...(v.comments||[]),{by:S.role,text:t,at:Date.now()}],status:admin()?'reviewed':'new',lastAt:Date.now()},admin()?logo('video',`${nm(v.memberId)} 영상에 피드백 등록`):logo('video',`${nm(v.memberId)} 영상에 답글`));delete S.f['fc_'+id]};
A.fvDel=async({id})=>{if(!await ask('영상을 삭제할까요?','','삭제',true))return;await delDoc('formvids',id)};

// ================= 내 정보 =================
function vMe(){const m=me();const sub=subOf('me','info');
 return `<div class="card hero mint"><div class="row nw" style="position:relative;z-index:1"><div style="width:56px;height:56px;border-radius:19px;background:rgba(255,255,255,.25);display:grid;place-items:center;font-weight:900;font-size:22px">${esc((m.name||'?').slice(0,1))}</div><div class="grow"><h2 style="color:#fff">${esc(m.name)}</h2><div class="xs muted">아이디 ${esc(m.loginId)}${m.endDate?` · 이용기한 ${esc(m.endDate)}`:''}</div></div></div>
 <div class="g3" style="position:relative;z-index:1">${[['총 회차',m.total||0,totSplit(m)],['진행',m.used||0,''],['총 잔여',remaining(m),remSplit(m)]].map(([l,v,x])=>`<div style="background:rgba(255,255,255,.18);border-radius:16px;padding:10px 12px"><div class="xs muted b">${l}</div><div class="big num" style="font-size:26px;color:#fff">${v}</div>${x?`<div class="xs onw">${x}</div>`:''}</div>`).join('')}</div><div class="bar" style="background:rgba(255,255,255,.3);position:relative;z-index:1"><i style="width:${m.total?Math.min(100,(m.used||0)/m.total*100):0}%;background:#fff"></i></div></div>
 ${seg('me',[['info','인바디'],['body','신체 정보'],['acct','계정 설정']],'info')}
 ${sub==='body'?`<div class="card">${profileForm(m.id)}<button class="btn pri full" data-a="saveProfile" data-m="${m.id}">저장</button></div>`:sub==='acct'?acctSec(m):inbodySec(m.id,false)}`}
function acctSec(m){return `<div class="card"><h3>아이디 / 비밀번호 변경</h3><div><label class="fl">아이디</label><input class="inp" data-f="ac_id" value="${esc(fv('ac_id',m.loginId))}" autocapitalize="off"></div><div><label class="fl">새 비밀번호 (바꿀 때만)</label><input class="inp" type="password" data-f="ac_pw1" value="${esc(fv('ac_pw1'))}"></div><div><label class="fl">새 비밀번호 확인</label><input class="inp" type="password" data-f="ac_pw2" value="${esc(fv('ac_pw2'))}"></div><div><label class="fl">현재 비밀번호 *</label><input class="inp" type="password" data-f="ac_pw0" value="${esc(fv('ac_pw0'))}"></div><button class="btn pri full" data-a="chgAcct">변경 저장</button></div>
 <div class="card"><h3>📅 예약을 휴대폰 캘린더에</h3>${icsBox(m.icsToken)}</div>
 <div class="card"><div class="row sb"><h3>화면 모드</h3><button class="btn soft" data-a="theme">${S.theme==='dark'?'☀️ 라이트 모드':'🌙 다크 모드'}</button></div></div><button class="btn ghost full" data-a="logout">${ic('out',16)} 로그아웃</button>`}
A.chgAcct=async()=>{const m=me();if(S.f.ac_pw1&&S.f.ac_pw1!==S.f.ac_pw2)return toast('새 비밀번호가 서로 달라요');const id=(S.f.ac_id||m.loginId).trim().toLowerCase();await act('account',{pw0:S.f.ac_pw0||'',loginId:id!==m.loginId?id:undefined,pw1:S.f.ac_pw1||undefined});clearF('ac_');toast('계정 정보를 변경했어요')};
const MET=[['weight','체중','kg'],['muscle','골격근량','kg'],['fatMass','체지방량','kg'],['fatPct','체지방률','%'],['bmi','BMI',''],['bmr','기초대사량','kcal'],['visceral','내장지방','레벨'],['score','인바디 점수','점']];
function inbodySec(mid,adm){const l=md(mid).inbody;const tr=[...l].reverse().slice(-8);const met=fv('ib_met','weight');const tv=tr.filter(x=>+x.metrics?.[met]);
 return `<div class="card"><h3>인바디 업로드</h3><p class="sm muted">인바디 결과지를 찍거나 스캔해서 올리면 AI가 수치를 읽고, 운동·식단·생활습관 방향을 자세히 알려드려요. 올린 결과지는 계속 다시 볼 수 있어요.</p>
 <label class="btn grad lg full">${S.busy['ib'+mid]?'<span class="spin"></span> 인바디를 분석하는 중… (최대 1분)':ic('cam',18)+' 인바디 결과지 올리기'}<input type="file" hidden accept="image/*,application/pdf" data-file="ibUp" data-m="${mid}" ${dis('ib'+mid)}></label>${!adm&&S.aiLeft&&!S.aiLeft.admin&&S.aiLeft.inbodyLimit?`<p class="xs muted" style="text-align:center">이번 달 인바디 AI 분석 <b>${S.aiLeft.inbody}</b>/${S.aiLeft.inbodyLimit}회 남음</p>`:''}</div>
 ${tr.length>1?`<div class="card"><div class="row sb"><h3>변화 추이</h3><select class="inp" style="width:auto" data-f="ib_met" data-rr>${MET.slice(0,6).map(([k,n])=>`<option value="${k}" ${met===k?'selected':''}>${n}</option>`).join('')}</select></div>${spark(tv.map(x=>n1(x.metrics[met])),tv.map(x=>(x.date||'').slice(5)))}</div>`:''}
 ${l.length?l.map(x=>`<div class="card tap" data-a="ibOpen" data-id="${x.id}" data-m="${mid}"><div class="row sb"><b>${fmtD(x.date)}</b><span class="xs pc b">분석 보기 →</span></div><div class="kv">${MET.slice(0,4).map(([k,n,u])=>x.metrics?.[k]!=null&&x.metrics[k]!==''?`<div><span>${n}</span><b>${esc(x.metrics[k])}<small class="xs"> ${u}</small></b></div>`:'').join('')}</div>${x.analysis?.summary?`<p class="sm muted ell">${esc(x.analysis.summary)}</p>`:''}</div>`).join(''):'<p class="empty">아직 올린 인바디가 없어요.</p>'}`}
const IB_PROMPT=(p,prev)=>`첨부는 인바디(체성분 분석) 결과지다. 결과지에 인쇄된 수치와 표준 범위를 빠짐없이 정확히 읽고, 전문 트레이너 관점에서 핵심만 쉽게 분석하라.
[회원 참고] 성별:${p.sex||'-'} 나이:${p.age||'-'} 키:${p.h||'-'} 목표:${p.goal||'-'} 질환:${p.disease||'없음'}${prev?`\n[이전 인바디 ${prev.date}] ${JSON.stringify(prev.metrics||{})} — 변화를 change에 구체적으로 적어라.`:''}
규칙: 결과지에 없는 값은 null(지어내지 말 것). ranges는 결과지에 표시된 표준 범위 [하한,상한]. 부위별(segLean, segFat)은 결과지의 부위별 근육/체지방 분석에서 kg와 %(표준 대비)와 판정(표준이하|표준|표준이상)을 읽는다. control은 결과지의 체중조절 항목(적정체중, 체중조절, 지방조절, 근육조절, + 또는 - 부호 포함).
type은 체형 판정(예: 표준, 근육형, 마른 비만, 경도 비만, 근육형 비만 등)과 쉬운 한 줄 이유. 글은 어르신도 바로 이해하도록 아주 쉬운 우리말로 짧게 쓴다: 골격근량·체지방률·내장지방·기초대사량 같은 인바디 전문용어는 그대로 쓰고 문장만 쉽게, 모든 문장은 한 문장 40자 안팎, 각 항목은 한 문장. concerns는 문제점, strengths는 좋은 점, exercise·diet·lifestyle은 앞으로 할 일(바로 따라 할 수 있게 구체적으로). change는 이전 측정과 비교 1~3개(이전이 없으면 빈 배열).
JSON: {"date":string|null,"metrics":{"weight":number|null,"muscle":number|null,"fatMass":number|null,"fatPct":number|null,"bmi":number|null,"bmr":number|null,"visceral":number|null,"score":number|null,"tbw":number|null,"ecwRatio":number|null,"protein":number|null,"mineral":number|null,"ffm":number|null,"whr":number|null},
"ranges":{"weight":[number,number]|null,"muscle":[number,number]|null,"fatMass":[number,number]|null,"fatPct":[number,number]|null,"bmi":[number,number]|null,"tbw":[number,number]|null,"protein":[number,number]|null,"mineral":[number,number]|null},
"segLean":{"rArm":{"kg":number|null,"pct":number|null,"level":string|null},"lArm":{...},"trunk":{...},"rLeg":{...},"lLeg":{...}},"segFat":{"rArm":{...},"lArm":{...},"trunk":{...},"rLeg":{...},"lLeg":{...}},
"control":{"target":number|null,"weight":number|null,"fat":number|null,"muscle":number|null},
"type":{"name":string,"why":string},"summary":"쉬운 말 2문장 종합","concerns":["문제점 2~3개"],"strengths":["좋은 점 2~3개"],"change":[string],
"exercise":["운동 방향 2~3개"],"diet":["식단 방향 2~3개(하루 단백질 g 등 숫자 포함)"],"lifestyle":["생활습관 1~2개"],"goals":{"period":"예: 12주","weight":string,"muscle":string,"fatPct":string}}`;
async function ibAnalyze(mid,fileId,prevOf){const p=S.members[mid]?.profile||{};if(S.aiLeft&&!S.aiLeft.admin&&S.aiLeft.inbody<=0)throw new Error(`인바디 분석은 한 달에 ${S.aiLeft.inbodyLimit||2}번까지 할 수 있어요. 더 필요하면 트레이너에게 문의해주세요.`);const a=await ai(IB_PROMPT(p,prevOf),{files:[fileId],kind:'inbody'});if(!a||!a.metrics)throw new Error('인바디를 읽지 못했어요. 결과지 전체가 선명하게 나오게 다시 찍어주세요.');a.v=2;return a}
A.ibUp=(d,files)=>busy('ib'+d.m,async()=>{const mid=d.m;if(S.aiLeft&&!S.aiLeft.admin&&S.aiLeft.inbody<=0)throw new Error(`인바디 분석은 한 달에 ${S.aiLeft.inbodyLimit||2}번까지 할 수 있어요. 더 필요하면 트레이너에게 문의해주세요.`);const f=files[0];const r=await upload(f,2400);const prev=md(mid).inbody[0];
 const a=await ibAnalyze(mid,r.id,prev);
 await put('inbody',uid(),{memberId:mid,fileId:r.id,ctype:r.type,date:/^\d{4}-\d{2}-\d{2}$/.test(a.date||'')?a.date:today(),metrics:a.metrics,analysis:a,createdAt:Date.now()},logo('inbody',`${nm(mid)} 인바디 업로드·AI 분석`));
 const mt=a.metrics,np={};if(mt.weight)np.w=mt.weight;if(mt.fatPct)np.fat=mt.fatPct;if(mt.muscle)np.mus=mt.muscle;if(mt.bmr)np.bmr=mt.bmr;if(Object.keys(np).length)await act('profile',{memberId:mid,profile:np});toast('인바디 분석이 완료됐어요')});
A.ibRe=({id,m:mid})=>busy('ibr'+id,async()=>{const l=md(mid).inbody;const i=l.findIndex(x=>x.id===id);const x=l[i];if(!x)return;const a=await ibAnalyze(mid,x.fileId,l[i+1]);
 await put('inbody',id,{...x,metrics:{...(x.metrics||{}),...Object.fromEntries(Object.entries(a.metrics).filter(([,v])=>v!=null))},analysis:a});toast('상세 분석을 다시 했어요');renderModal()});
const IBX=[['weight','체중','kg'],['muscle','골격근량','kg'],['fatMass','체지방량','kg'],['fatPct','체지방률','%'],['bmi','BMI',''],['tbw','체수분','L'],['protein','단백질','kg'],['mineral','무기질','kg']];
function ibGauge(v,r){v=+v;if(!r||r.length!==2||!(+r[1]>+r[0]))return '';const lo=+r[0],hi=+r[1];const min=lo-(hi-lo)*.9,max=hi+(hi-lo)*1.6;const pos=Math.max(2,Math.min(98,(v-min)/(max-min)*100));const st=v<lo?['표준이하','#E07A2F']:v>hi?['표준이상','#D9466A']:['표준','#16A37A'];
 return `<div class="ibg"><div class="ibgt"><i style="left:${(lo-min)/(max-min)*100}%;width:${(hi-lo)/(max-min)*100}%"></i><b style="left:${pos}%;background:${st[1]}"></b></div><div class="row sb xs muted"><span>표준 ${lo}~${hi}</span><span style="color:${st[1]};font-weight:800">${st[0]}</span></div></div>`}
function ibSeg(seg,title,unit){if(!seg)return '';const c=k=>{const x=seg[k]||{};const lv=x.level||'';const col=/이하/.test(lv)?'#E07A2F':/이상/.test(lv)?'#D9466A':lv?'#16A37A':'var(--mu)';return `<div class="sg" style="border-color:${col}"><div class="xs muted">${{lArm:'왼팔',rArm:'오른팔',trunk:'몸통',lLeg:'왼다리',rLeg:'오른다리'}[k]}</div><b class="num">${x.kg!=null?x.kg+'kg':'-'}</b>${x.pct!=null?`<div class="xs muted num">${x.pct}%</div>`:''}${lv?`<div class="xs b" style="color:${col}">${esc(lv)}</div>`:''}</div>`};
 return `<div class="sec"><h4>${title}</h4><div class="segw"><div class="segg">${c('rArm')}${c('trunk')}${c('lArm')}${c('rLeg')}<div></div>${c('lLeg')}</div></div></div>`}
A.ibOpen=({id,m:mid})=>{openModal(()=>{const x=md(mid).inbody.find(i=>i.id===id);if(!x)return mh('인바디');const a=x.analysis||{};const m=x.metrics||{};const R=a.ranges||{};const C=a.control||{};const B=a.balance||{};
 return `${mh(`인바디 · ${fmtD(x.date)}`)}${x.ctype?.startsWith('image')?`<div class="media"><img src="${fileUrl(x.fileId)}" alt="인바디 결과지"></div>`:`<a class="btn full" href="${fileUrl(x.fileId)}" target="_blank" rel="noopener">${ic('file',16)} 원본 PDF 보기</a>`}
 ${a.v!==2?`<div class="note">더 자세한 분석(표준 범위 · 부위별 균형 · 체수분 · 체중 조절)을 볼 수 있어요.</div><button class="btn grad full" data-a="ibRe" data-id="${x.id}" data-m="${mid}" ${dis('ibr'+x.id)}>${bz('ibr'+x.id,ic('spark',16)+' 상세 분석하기','분석 중… (최대 1분)')}</button>`:''}
 ${a.type?.name?`<div class="card tint1"><div class="xs muted b">체형 판정</div><div style="font-size:22px;font-weight:900;margin:4px 0">${esc(a.type.name)}</div><p class="sm">${esc(a.type.why||'')}</p></div>`:''}
 ${a.summary?`<div class="card"><div class="sec"><h4>한 줄 요약</h4><p class="sm">${esc(a.summary)}</p></div></div>`:''}
 ${a.concerns?.length||a.strengths?.length||a.exercise?.length?`<div class="card col ibez">${a.concerns?.length?`<div class="ibz bad"><h4>😟 이런 점이 문제예요</h4>${ul(a.concerns)}</div>`:''}${a.strengths?.length?`<div class="ibz good"><h4>👍 이런 점은 좋아요</h4>${ul(a.strengths)}</div>`:''}${(a.exercise||[]).length+(a.diet||[]).length+(a.lifestyle||[]).length?`<div class="ibz go"><h4>👉 앞으로 이렇게 해요</h4>${[['🏋️ 운동',a.exercise],['🥗 식사',a.diet],['🌙 생활',a.lifestyle]].filter(([,l])=>l?.length).map(([t,l])=>`<div class="xs b muted" style="margin-top:6px">${t}</div>${ul(l)}`).join('')}</div>`:''}</div>`:''}
 <div class="card col"><h4 style="margin:0">체성분 · 표준 범위 비교</h4>${IBX.filter(([k])=>m[k]!=null&&m[k]!=='').map(([k,n,u])=>`<div><div class="row sb"><span class="sm b">${n}</span><b class="num">${esc(m[k])}<small class="xs muted"> ${u}</small></b></div>${ibGauge(m[k],R[k])}</div>`).join('')}
 <div class="kv">${[['bmr','기초대사량','kcal'],['visceral','내장지방','레벨'],['ecwRatio','세포외수분비',''],['ffm','제지방량','kg'],['whr','복부지방률',''],['score','인바디 점수','점']].map(([k,n,u])=>m[k]!=null&&m[k]!==''?`<div><span>${n}</span><b>${esc(m[k])}<small class="xs"> ${u}</small></b></div>`:'').join('')}</div>
 ${m.ecwRatio?`<p class="xs muted">세포외수분비 ${m.ecwRatio>0.39?'<b style="color:#D9466A">0.39 초과 — 부기(부종) 가능성</b>':'0.36~0.39 정상 범위'}</p>`:''}</div>
 ${a.segLean||a.segFat?`<div class="card col">${ibSeg(a.segLean,'부위별 근육량','kg')}${ibSeg(a.segFat,'부위별 체지방량','kg')}</div>`:''}
 ${C.target!=null||C.fat!=null?`<div class="card"><div class="sec"><h4>체중 조절 목표</h4><div class="kv">${C.target!=null?`<div><span>적정 체중</span><b>${esc(C.target)}<small class="xs"> kg</small></b></div>`:''}${C.weight!=null?`<div><span>체중 조절</span><b>${C.weight>0?'+':''}${esc(C.weight)}<small class="xs"> kg</small></b></div>`:''}${C.fat!=null?`<div><span>지방 조절</span><b>${C.fat>0?'+':''}${esc(C.fat)}<small class="xs"> kg</small></b></div>`:''}${C.muscle!=null?`<div><span>근육 조절</span><b>${C.muscle>0?'+':''}${esc(C.muscle)}<small class="xs"> kg</small></b></div>`:''}</div></div></div>`:''}
 ${a.change?.length?`<div class="card"><div class="sec"><h4>📈 지난 측정과 비교</h4>${ul(a.change)}</div></div>`:''}
 ${a.goals?`<div class="card"><div class="sec"><h4>🎯 목표 (${esc(a.goals.period||'')})</h4><div class="kv">${a.goals.weight?`<div><span>체중</span><b class="sm">${esc(a.goals.weight)}</b></div>`:''}${a.goals.muscle?`<div><span>골격근량</span><b class="sm">${esc(a.goals.muscle)}</b></div>`:''}${a.goals.fatPct?`<div><span>체지방률</span><b class="sm">${esc(a.goals.fatPct)}</b></div>`:''}</div></div></div>`:''}
 ${a.v===2?`<button class="btn ghost full" data-a="ibRe" data-id="${x.id}" data-m="${mid}" ${dis('ibr'+x.id)}>${bz('ibr'+x.id,ic('refresh',15)+' 다시 분석','분석 중…')}</button>`:''}
 <p class="xs muted">AI 분석은 참고용이며 의학적 진단이 아니에요.</p><button class="btn ghost dng full" data-a="ibDel" data-id="${x.id}">이 인바디 삭제</button>`})};
A.ibDel=async({id})=>{if(!await ask('인바디 기록을 삭제할까요?','','삭제',true))return;await delDoc('inbody',id);closeModal()};

// ================= 관리자 =================
function vAdmin(){const nav=[['home','대시보드','home'],['members','회원','users'],['book','예약','cal'],['content','콘텐츠','grid'],['settings','설정','gear']];
 const b={home:vAHome,members:vAMembers,book:vABook,content:vAContent,settings:vASettings}[S.tab]||vAHome;return shell(nav,b())}
const members=()=>Object.values(S.members).filter(m=>m.role!=='admin');
const AICON={book:'📅',cancel:'✖️',change:'🔁',done:'✅',noshow:'⚠️',workout:'🏋️',meal:'🍽️',video:'🎬',inbody:'📊',routine:'✨',diet:'🥗',member:'👤'};
function vAHome(){const ms=members();const act_=ms.filter(m=>mstate(m)==='active');const exp=ms.filter(m=>mstate(m)==='expired');const tb=S.bookings.filter(b=>b.date===today()).sort(byDT);const wk=S.bookings.filter(b=>b.status==='booked'&&b.date>=today()&&b.date<=addDays(today(),7)).length;const nv=S.formvids.filter(v=>v.status!=='reviewed').length;const low=act_.filter(m=>remaining(m)<=2&&(+m.total||0)>0);
 const af=S.sub.afeed||'all';const feed=S.activity.filter(a=>af==='all'||(af==='bk'?['book','cancel','change','done','noshow'].includes(a.kind):af==='wk'?['workout','routine'].includes(a.kind):['meal','diet','inbody','video'].includes(a.kind)));
 return `<button class="vacard" data-a="viewAs"><span class="vaic">👀</span><span class="grow" style="text-align:left"><b>회원 화면으로 전환</b><span class="xs">회원이 보는 앱 화면을 그대로 확인해요</span></span>${ic('right',18)}</button><div class="card hero"><div style="position:relative;z-index:1"><div class="muted sm">${fmtD(today())}</div><h1 style="color:#fff">${esc(me().name||'트레이너')}님, 오늘 수업 ${tb.filter(b=>b.status!=='noshow').length}건이에요</h1></div>
 <div class="g4" style="position:relative;z-index:1">${[['등록 회원',act_.length,'members','active'],['만료 회원',exp.length,'members','expired'],['7일 내 예약',wk,'book'],['확인 대기 영상',nv,'content','fv']].map(([l,v,t,s])=>`<div class="tap" data-a="${t==='members'?'memFilterGo':'go'}" data-t="${t}" data-v="${s||''}" data-s="${t==='content'?s:''}" style="background:rgba(255,255,255,.18);border-radius:16px;padding:10px 12px"><div class="xs muted b">${l}</div><div class="big num" style="font-size:26px;color:#fff">${v}</div></div>`).join('')}</div></div>
 <div class="card"><div class="row sb"><h3>오늘 일정</h3><button class="btn sm soft" data-a="go" data-t="book">캘린더</button></div>${tb.length?tb.map(b=>adminBk(b)).join('<div style="height:8px"></div>'):'<p class="empty">오늘 예약이 없어요.</p>'}</div>
 <div class="card"><div class="row sb"><h3>오늘 회원 식단 현황</h3><span class="xs muted">탭하면 확인·코멘트</span></div>${act_.length?`<div class="list">${act_.sort((a,b)=>a.name.localeCompare(b.name)).map(m=>{const ml=md(m.id).meals[today()];const rv=Object.values(ml?.review||{}).filter(r=>r?.ok||r?.comment).length;const n=SLOTS.filter(s=>slotFilled(ml,s[0])).length;return `<div class="li tap" data-a="memOpen" data-id="${m.id}" data-tab="diet"><b class="grow">${esc(m.name)}</b><span>${SLOTS.map(([k,,e])=>`<span style="opacity:${slotFilled(ml,k)?1:.2}">${e}</span>`).join(' ')}</span>${n&&rv<n?'<span class="chip y xs">확인 필요</span>':n?'<span class="chip g xs">확인 완료</span>':''}</div>`}).join('')}</div>`:'<p class="empty">등록된 회원이 없어요.</p>'}</div>
 ${low.length?`<div class="card"><h3>재등록 안내가 필요한 회원</h3><div class="list">${low.map(m=>`<div class="li tap" data-a="memOpen" data-id="${m.id}"><b class="grow">${esc(m.name)}</b><span class="chip y">잔여 ${remaining(m)}회</span></div>`).join('')}</div></div>`:''}
 <div class="card"><h3>회원 업데이트 내역</h3>${seg('afeed',[['all','전체'],['bk','예약'],['wk','운동'],['dt','식단·인바디·영상']],'all')}${feed.length?(()=>{const P=paged(feed,'feed_'+af,7);return `<div class="list" id="pg-feed_${af}">${P.items.map(a=>`<div class="act ${a.memberId?'tap':''}" ${a.memberId&&S.members[a.memberId]?`data-a="memOpen" data-id="${a.memberId}"`:''}><div class="e">${AICON[a.kind]||'•'}</div><div class="grow"><div>${esc(a.text)}</div><div class="xs muted">${ago(a.at)}${a.by==='member'?' · 회원':a.by==='admin'?' · 관리자':''}</div></div></div>`).join('')}</div>${pagerHTML('feed_'+af,P.pg,P.pages,feed.length,7)}`})():'<p class="empty">아직 내역이 없어요.</p>'}</div>`}
A.memFilterGo=({v})=>{S.memFilter=v;S.tab='members';S.selMember=null;render()};
function adminBk(b){const past=slotDT(b.date,b.time)<new Date();return `<div class="bk"><div class="t num">${b.time}</div><div class="grow"><b class="tap" data-a="memOpen" data-id="${b.memberId}">${esc(nm(b.memberId)||b.memberName)}</b> <span class="tag ${b.type==='consult'?'c':''}">${typeName(b.type)}</span> ${b.status==='done'?'<span class="tag d">완료</span>':b.status==='noshow'?'<span class="tag n">노쇼</span>':''}${b.memo?`<div class="xs muted">💬 ${esc(b.memo)}</div>`:''}${b.changedFrom?`<div class="xs muted">🔁 ${esc(b.changedFrom)}에서 변경</div>`:''}</div>
 <div class="row" style="gap:4px;justify-content:flex-end">${b.status==='booked'?`<button class="btn sm pri" data-a="bkSt" data-id="${b.id}" data-v="done">완료</button>${past&&b.type==='lesson'?`<button class="btn sm" data-a="bkNoShow" data-id="${b.id}">노쇼</button>`:''}<button class="btn sm ghost dng" data-a="bkAdminCancel" data-id="${b.id}">취소</button>`:`<button class="btn sm ghost" data-a="bkSt" data-id="${b.id}" data-v="booked">되돌리기</button>`}</div></div>`}
A.bkSt=async({id,v})=>{const b=S.bookingMap[id];await act('book/status',{id,status:v});if(v==='done'){const m=S.members[b.memberId];toast(`${m?.name} ${typeName(b.type)} 완료${b.type==='lesson'?` · ${m?.used||0}/${m?.total||0}회`:''}`)}else toast('되돌렸어요')};
A.bkNoShow=async({id})=>{const ded=await ask('노쇼 처리','회차를 1회 차감할까요? (취소를 누르면 차감 없이 노쇼만 기록)','차감');await act('book/status',{id,status:'noshow',deduct:ded})};
A.bkAdminCancel=async({id})=>{const b=S.bookingMap[id];if(!await ask('예약을 취소할까요?',`${nm(b.memberId)} · ${fmtD(b.date)} ${b.time} (관리자는 시간 제한 없이 취소할 수 있어요)`,'예약 취소',true))return;await act('book/cancel',{id});toast('취소했어요')};
// ---- 회원 관리 ----
function vAMembers(){if(S.selMember&&S.members[S.selMember])return memberDetail(S.selMember);const f=S.memFilter;const fm=(m,k)=>k==='all'||(k==='rereg'?needReReg(m):k==='regd'?reRegCount(m)>0:mstate(m)===k);const cnt=k=>members().filter(m=>fm(m,k)).length;
 return `<div class="row sb"><h1>회원 관리</h1><button class="btn grad" data-a="memNew">${ic('plus',16)} 회원 등록</button></div>
 <div class="pills">${[['active','이용중'],['rereg','재등록 필요'],['regd','재등록 회원'],['expired','만료'],['blocked','차단'],['all','전체']].map(([k,l])=>`<button class="pill ${f===k?'on':''}" data-a="memFilter" data-v="${k}">${l} ${cnt(k)}</button>`).join('')}</div>
 <input class="inp" placeholder="이름·아이디 검색" data-f="memQ" data-live="mem" value="${esc(fv('memQ'))}">
 ${f==='expired'&&cnt('expired')?`<button class="btn soft full" data-a="blockExpired">만료 회원 ${cnt('expired')}명 모두 로그인 차단</button>`:''}<div id="p-mem">${PART.mem()}</div>`}
PART.mem=()=>{const q=(S.f.memQ||'').trim().toLowerCase();const k0=S.memFilter;const l=members().filter(m=>(k0==='all'||(k0==='rereg'?needReReg(m):k0==='regd'?reRegCount(m)>0:mstate(m)===k0))&&(!q||(m.name||'').toLowerCase().includes(q)||(m.loginId||'').includes(q))).sort((a,b)=>(a.name||'').localeCompare(b.name||''));
 return l.length?`<div class="col">${l.map(m=>{const nb=futureOf(m.id)[0];return `<div class="card tap" data-a="memOpen" data-id="${m.id}" style="padding:15px"><div class="row sb nw"><div class="ell"><b>${esc(m.name)}</b> <span class="xs muted">${esc(m.loginId)}</span></div><span class="row nw" style="gap:4px">${regBadges(m)}${stChip(m)}</span></div><div class="row sb"><span class="sm num">등록 <b>${m.total||0}</b>회 · 진행 <b>${m.used||0}</b>회 · 총 잔여 <b class="pc">${remaining(m)}</b>회${remSplit(m)}</span><span class="xs muted">${nb?`다음 ${nb.date.slice(5)} ${nb.time}`:'예약 없음'}</span></div><div class="bar"><i style="width:${m.total?Math.min(100,(m.used||0)/m.total*100):0}%"></i></div></div>`}).join('')}</div>`:'<p class="empty">해당하는 회원이 없어요.</p>'};
A.memFilter=({v})=>{S.memFilter=v;render()};
const reRegCount=m=>(m.history||[]).filter(h=>String(h.text||'').startsWith('재등록')).length;
const needReReg=m=>m.role!=='admin'&&!m.blocked&&(+m.total||0)>0&&(remaining(m)<=2||isExpired(m));
const regBadges=m=>`${needReReg(m)?'<span class="chip y">재등록 필요</span>':''}${reRegCount(m)?`<span class="chip p">재등록 회원${reRegCount(m)>1?` · ${reRegCount(m)}회`:''}</span>`:''}`;
A.blockExpired=async()=>{const n=members().filter(m=>mstate(m)==='expired').length;if(!await ask(`${n}명을 차단할까요?`,'차단된 회원은 로그인할 수 없어요. 재등록하면 자동으로 해제돼요.','차단',true))return;await act('admin/blockExpired',{});toast('차단했어요')};
A.memNew=()=>{clearF('nm_');S.f.nm_start=today();openModal(()=>{const i=(k,l,t='text',ph='')=>`<div><label class="fl">${l}</label><input class="inp" type="${t}" data-f="${k}" value="${esc(fv(k))}" placeholder="${ph}" ${t==='number'?'inputmode="numeric"':''} autocapitalize="off"></div>`;
 return `${mh('회원 등록')}<div class="fg">${i('nm_name','이름 *')}${i('nm_phone','연락처','tel')}${i('nm_id','로그인 아이디 *','text','영문·숫자')}${i('nm_pw','임시 비밀번호 *','text','4자 이상')}${i('nm_total','결제 회차 *','number','예: 20')}${i('nm_bonus','서비스 회차','number','이벤트 등 (선택)')}${i('nm_used','이미 진행한 회차','number','0')}${i('nm_start','시작일','date')}${i('nm_end','종료일 (선택)','date')}</div>${i('nm_memo','메모','text','목표, 특이사항 등')}
 <p class="xs muted">회원에게 앱 주소, 아이디, 임시 비밀번호, 회원 전용코드를 알려주세요. 회원은 '내 정보'에서 아이디와 비밀번호를 바꿀 수 있어요.</p><button class="btn grad lg full" data-a="memCreate">등록하기</button>`})};
A.memCreate=async()=>{const g=k=>(S.f[k]||'').toString().trim();if(!g('nm_name')||!g('nm_id')||!g('nm_pw')||!g('nm_total'))return toast('* 표시 항목을 입력해주세요');
 const bn=Math.max(0,parseInt(g('nm_bonus'))||0);const r=await api('POST','/api/admin/member',{name:g('nm_name'),phone:g('nm_phone'),loginId:g('nm_id'),pw:g('nm_pw'),total:(parseInt(g('nm_total'))||0)+bn,used:g('nm_used')||0,startDate:g('nm_start')||today(),endDate:g('nm_end'),memo:g('nm_memo')});if(bn&&r&&r.id)await api('POST','/api/profile',{memberId:r.id,profile:{bonus:bn,bonusAll:bn}});await sync();render();clearF('nm_');closeModal();toast('회원을 등록했어요');S.memFilter='active'};
A.memOpen=({id,tab})=>{if(!S.members[id])return;clearF('ed_');S.selMember=id;S.tab='members';S.sub.mem=tab||'info';S.wlDate=null;S.dietDate=null;if(tab==='diet')S.sub.adiet='today';window.scrollTo(0,0);render()};
A.memBack=()=>{S.selMember=null;render()};
function memberDetail(mid){const m=S.members[mid];const cur=subOf('mem','info');
 return `<div class="row nw"><button class="ib" data-a="memBack">${ic('left')}</button><div class="grow"><h2 class="ell">${esc(m.name)}</h2><div class="xs muted">${esc(m.loginId)} · 등록 ${m.total||0}회 · 진행 ${m.used||0}회 · 총 잔여 ${remaining(m)}회${remSplit(m)}</div>${regBadges(m)?`<div class="row" style="gap:4px;margin-top:4px">${regBadges(m)}</div>`:''}</div>${stChip(m)}</div>
 <button class="btn soft full" data-a="viewAs" data-id="${mid}">👀 ${esc(m.name)}님이 보는 화면으로 보기</button>
 <div class="pills">${[['info','기본 정보'],['work','운동'],['diet','식단'],['inbody','인바디'],['video','영상'],['book','예약']].map(([k,l])=>`<button class="pill ${cur===k?'on':''}" data-a="sub" data-k="mem" data-v="${k}">${l}</button>`).join('')}</div>
 ${cur==='work'?vWorkout(mid,true):cur==='diet'?vDiet(mid,true):cur==='inbody'?`${inbodySec(mid,true)}<div class="card"><h3>신체 정보</h3>${profileForm(mid)}<button class="btn full" data-a="saveProfile" data-m="${mid}">저장</button></div>`:cur==='video'?formVidSec(mid,true):cur==='book'?memBookings(mid):memInfo(m)}`}
function memInfo(m){const i=(k,l,v,t='text')=>`<div><label class="fl">${l}</label><input class="inp" type="${t}" data-f="ed_${k}" value="${esc(fv('ed_'+k,v??''))}"></div>`;
 return `<div class="card"><h3>수업 회차</h3><div class="g3">${[['등록',m.total||0,totSplit(m)],['진행',m.used||0,''],['총 잔여',remaining(m),remSplit(m)]].map(([l,v,x],j)=>`<div class="stat"><div class="l">${l}</div><div class="v ${j===2?'pc':''}">${v}<small class="xs">회</small></div>${x?`<div class="xs">${x}</div>`:''}</div>`).join('')}</div>${svcLeft(m)||svcAll(m)?`<p class="xs muted"><span class="svc">보라색</span>은 서비스 세션이에요. 결제한 회차를 먼저 쓰고, 서비스 회차는 마지막에 차감돼요.</p>`:''}
 <div class="row"><span class="sm muted grow">진행 회차 수동 조정</span><button class="btn sm" data-a="usedAdj" data-id="${m.id}" data-v="-1">−1</button><button class="btn sm" data-a="usedAdj" data-id="${m.id}" data-v="1">+1</button></div>
 <div class="row nw"><input class="inp" type="number" inputmode="numeric" placeholder="결제 회차" data-f="ed_add" value="${esc(fv('ed_add'))}"><input class="inp" type="number" inputmode="numeric" placeholder="서비스 (선택)" data-f="ed_bonus" value="${esc(fv('ed_bonus'))}" style="max-width:120px"><button class="btn pri" data-a="reReg" data-id="${m.id}">재등록</button></div><div class="row nw"><input class="inp" type="number" inputmode="numeric" placeholder="서비스 세션만 추가" data-f="ed_svc" value="${esc(fv('ed_svc'))}"><button class="btn soft" data-a="svcAdd" data-id="${m.id}">서비스 부여</button></div>
 <p class="xs muted">예약에서 '완료'를 누르면 진행 회차가 즉시 1 올라가요. 재등록하면 차단도 자동 해제돼요.</p>
 ${(m.history||[]).length?`<details><summary class="sm muted">등록 이력 ${m.history.length}건</summary><div class="list">${[...m.history].reverse().map(h=>`<div class="li sm"><span class="grow">${esc(h.text)}</span><span class="xs muted">${new Date(h.at).toLocaleDateString('ko-KR')}</span></div>`).join('')}</div></details>`:''}</div>
 <div class="card"><div class="row sb"><h3>✨ AI 생성 횟수</h3><button class="btn sm soft" data-a="aiReset" data-id="${m.id}">다시 3회로</button></div><div class="g2"><div class="stat"><div class="l">AI 운동 루틴</div><div class="v">${(m.aiUse||{}).routine||0}<small class="xs muted"> / 3회 사용</small></div></div><div class="stat"><div class="l">AI 식단</div><div class="v">${(m.aiUse||{}).diet||0}<small class="xs muted"> / 3회 사용</small></div></div></div><p class="xs muted">회원은 등록 기간 동안 각각 3번까지 만들 수 있어요. 재등록하면 자동으로 다시 3회가 돼요. 트레이너가 대신 만들어 주는 건 횟수에 포함되지 않아요.</p></div>
 <div class="card"><div class="row sb"><h3>로그인 차단</h3><button class="btn ${m.blocked?'pri':'soft dng'}" data-a="toggleBlock" data-id="${m.id}">${m.blocked?'차단 해제':'로그인 차단'}</button></div><p class="xs muted">${m.blocked?'현재 이 회원은 로그인할 수 없어요.':isExpired(m)?(S.settings.autoBlock!==false?'만료 상태라 자동으로 로그인이 막혀 있어요.':'만료 상태지만 로그인은 가능해요.'):'정상 이용 중이에요.'}</p></div>
 <div class="card"><h3>회원 정보</h3><div class="fg">${i('name','이름',m.name)}${i('phone','연락처',m.phone,'tel')}${i('start','시작일',m.startDate,'date')}${i('end','종료일',m.endDate,'date')}${i('loginId','아이디',m.loginId)}${i('pw','비밀번호 초기화','')}</div>${i('memo','메모',m.memo)}<button class="btn pri full" data-a="memSave" data-id="${m.id}">정보 저장</button>
 <div class="xs muted">마지막 로그인 ${m.lastLogin?ago(m.lastLogin):'없음'}</div></div>
 <button class="btn ghost dng full" data-a="memDel" data-id="${m.id}">회원 삭제</button>`}
function memBookings(mid){const l=S.bookings.filter(b=>b.memberId===mid).sort(byDT).reverse();const acts0=S.activity.filter(a=>a.memberId===mid);const AP=paged(acts0,'ma_'+mid,7);const acts=AP.items;
 return `<div class="row nw"><button class="btn grad" style="flex:1" data-a="wkOpen" data-mem="${mid}">${ic('cal',16)} 주간 일정 한 번에</button><button class="btn soft" style="flex:1" data-a="abAdd" data-mem="${mid}">${ic('plus',16)} 1건 추가</button></div><div class="card"><h3>예약 내역</h3>${l.length?l.map(b=>adminBk(b)).join('<div style="height:8px"></div>'):'<p class="empty">예약이 없어요.</p>'}</div>${acts.length?`<div class="card"><h3>업데이트 내역 <span class="muted sm">최근 7일</span></h3><div class="list" id="pg-ma_${mid}">${acts.map(a=>`<div class="act"><div class="e">${AICON[a.kind]||'•'}</div><div class="grow"><div class="sm">${esc(a.text)}</div><div class="xs muted">${ago(a.at)}</div></div></div>`).join('')}</div>${pagerHTML('ma_'+mid,AP.pg,AP.pages,acts0.length,7)}</div>`:''}`}
A.usedAdj=async({id,v})=>{await act('admin/member',{id,usedDelta:+v})};
A.reReg=async({id})=>{const n=parseInt(S.f.ed_add)||0,b=Math.max(0,parseInt(S.f.ed_bonus)||0);if(n<1)return toast('결제한 회차를 입력해주세요');const m=S.members[id];const carry=svcLeft(m),all=svcAll(m);
 await api('POST','/api/admin/member',{id,addSessions:n+b});await api('POST','/api/profile',{memberId:id,profile:{bonus:carry+b,bonusAll:all+b}});await sync();render();delete S.f.ed_add;delete S.f.ed_bonus;toast(b?`결제 ${n}회 + 서비스 ${b}회 추가했어요`:`${n}회 추가했어요`)};
A.svcAdd=async({id})=>{const b=parseInt(S.f.ed_svc)||0;if(b<1)return toast('서비스 회차를 입력해주세요');const m=S.members[id];
 if(!await ask(`${m.name}님에게 서비스 ${b}회를 줄까요?`,'총 잔여 회차에 더해지고, 보라색으로 구분돼요.','부여하기'))return;
 const carry=svcLeft(m),all=svcAll(m);await api('POST','/api/admin/member',{id,total:(+m.total||0)+b,blocked:false});await api('POST','/api/profile',{memberId:id,profile:{bonus:carry+b,bonusAll:all+b}});await sync();render();delete S.f.ed_svc;toast(`서비스 ${b}회를 부여했어요`)};
A.aiReset=async({id})=>{const m=S.members[id];if(!await ask(`${m.name}님의 AI 생성 횟수를 다시 3회로 채울까요?`,'','다시 채우기'))return;await act('admin/member',{id,resetAi:true});toast('AI 생성 횟수를 다시 채웠어요')};
A.toggleBlock=async({id})=>{const m=S.members[id];await act('admin/member',{id,blocked:!m.blocked});toast(m.blocked?'차단을 해제했어요':'로그인을 차단했어요')};
A.memSave=async({id})=>{const m=S.members[id];const g=(k,d)=>fv('ed_'+k,d??'');const b={id,name:g('name',m.name).trim()||m.name,phone:g('phone',m.phone),startDate:g('start',m.startDate),endDate:g('end',m.endDate),memo:g('memo',m.memo)};const lid=g('loginId',m.loginId).trim();if(lid!==m.loginId)b.loginId=lid;if(S.f.ed_pw)b.pw=S.f.ed_pw;await act('admin/member',b);clearF('ed_');toast(b.pw?'저장했어요. 새 비밀번호를 회원에게 알려주세요.':'저장했어요')};
A.memDel=async({id})=>{const m=S.members[id];if(!await ask(`${m.name} 회원을 삭제할까요?`,'계정이 삭제되어 로그인할 수 없게 돼요.','삭제',true))return;await act('admin/member/delete',{id});C('members').delete(id);derive();S.selMember=null;render()};
// ---- 예약 관리 ----
function vABook(){const sel=S.abDate||today();const cnt=dt=>S.bookings.filter(b=>b.date===dt).length;const up=S.bookings.filter(b=>b.status==='booked'&&slotDT(b.date,b.time)>new Date()).sort(byDT).slice(0,15);
 const cs=calS();return `<h1>예약 관리</h1>${(cs.removed||[]).length||cs.ok===false?`<div class="note w tap" data-a="goCal" style="margin-bottom:10px">📅 ${cs.ok===false?'캘린더를 읽지 못했어요':`캘린더에서 지워진 일정 ${cs.removed.length}건 — 예약을 취소할지 확인해주세요`} ›</div>`:''}<button class="btn grad full" data-a="wkOpen" style="margin-bottom:12px">${ic('cal',17)} 회원 다음주 일정 한 번에 예약</button><div class="card">${calHTML('abDate',sel,dt=>{const c=cnt(dt);return c?`<span class="cnt">${c}건</span>`:dayClosed(dt)?'<span class="cnt" style="color:var(--hot)">휴무</span>':'<span class="mk"></span>'})}</div>
 <div class="card"><div class="row sb"><h3>${fmtD(sel)}</h3><button class="btn sm ${S.blocks[sel+'_all']?'pri':'ghost'}" data-a="blockDay" data-d="${sel}">${S.blocks[sel+'_all']?'휴무 해제':'이 날 휴무'}</button></div>
 ${[...new Set([...slotsFor(),...S.bookings.filter(b=>b.date===sel).map(b=>b.time)])].sort().map(t=>{const id=sid(sel,t);const b=S.bookingMap[id];if(b)return adminBk(b);const blk=S.blocks[id]||dayClosed(sel);const past=slotDT(sel,t)<new Date();return `<div class="bk" style="opacity:${blk||past?.5:1}"><div class="t num">${t}</div><div class="grow"><span class="sm muted">${blk?'예약 불가':past?'지남':'비어 있음'}</span></div>${S.blocks[sel+'_all']||past?'':`<button class="btn sm ghost" data-a="blockSlot" data-id="${id}" data-d="${sel}" data-t="${t}">${S.blocks[id]?'열기':'막기'}</button>`}${blk||past?'':`<button class="btn sm soft" data-a="abAdd" data-d="${sel}" data-t="${t}">${ic('plus',14)}</button>`}</div>`}).join('<div style="height:6px"></div>')}</div>
 <div class="card"><h3>다가오는 예약</h3>${up.length?`<div class="list">${up.map(b=>`<div class="li tap" data-a="abDate" data-d="${b.date}"><span class="num b" style="width:96px">${b.date.slice(5)} ${b.time}</span><span class="grow">${esc(nm(b.memberId))}</span><span class="tag ${b.type==='consult'?'c':''}">${typeName(b.type)}</span></div>`).join('')}</div>`:'<p class="empty">다가오는 예약이 없어요.</p>'}</div>
 <div class="card"><h3>📅 내 캘린더와 연동</h3><p class="sm muted">모든 예약·변경·취소가 구글/아이폰/네이버 캘린더에 자동 반영돼요.</p>${icsBox(S.settings.icsToken)}</div>`}
A.abDate=({d})=>{S.abDate=d;const x=parseD(d);S.cal={y:x.getFullYear(),m:x.getMonth()};render()};
A.blockDay=async({d})=>{const id=d+'_all';if(S.blocks[id])await delDoc('blocks',id);else{const n=S.bookings.filter(b=>b.date===d&&b.status==='booked').length;if(n&&!await ask('휴무로 지정할까요?',`이미 예약 ${n}건이 있어요. 기존 예약은 유지되니 따로 취소해주세요.`,'휴무 지정'))return;await put('blocks',id,{date:d,all:true,at:Date.now()})}};
A.blockSlot=async({id,d,t})=>{if(S.blocks[id])await delDoc('blocks',id);else await put('blocks',id,{date:d,time:t,at:Date.now()})};
A.abAdd=({d,t,mem})=>{clearF('ab_');S.f.ab_type='lesson';if(mem)S.f.ab_mem=mem;S.f.ab_d=d||today();S.f.ab_t=t||'';openModal(()=>{const ms=members().filter(m=>mstate(m)==='active').sort((a,b)=>a.name.localeCompare(b.name));return `${mh('예약 추가')}<div class="fg"><div><label class="fl">날짜</label><input class="inp" type="date" data-f="ab_d" value="${esc(fv('ab_d'))}"></div><div><label class="fl">시간</label><select class="inp" data-f="ab_t"><option value="">선택</option>${slotsFor().map(x=>`<option ${fv('ab_t')===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div><label class="fl">회원</label><select class="inp" data-f="ab_mem"><option value="">선택</option>${ms.map(m=>`<option value="${m.id}" ${fv('ab_mem')===m.id?'selected':''}>${esc(m.name)} (예약 가능 ${reservable(m)}회)</option>`).join('')}</select></div>
 <div class="seg">${[['lesson','PT 수업'],['consult','PT 상담']].map(([v,l])=>`<button class="${fv('ab_type')===v?'on':''}" data-a="abType" data-v="${v}">${l}</button>`).join('')}</div><input class="inp" placeholder="메모" data-f="ab_memo" value="${esc(fv('ab_memo'))}"><button class="btn grad lg full" data-a="abSave">예약 추가</button>`})};
A.abType=({v})=>{S.f.ab_type=v;renderModal()};
A.abSave=async()=>{if(!S.f.ab_mem||!S.f.ab_t||!S.f.ab_d)return toast('날짜, 시간, 회원을 선택해주세요');await act('book',{memberId:S.f.ab_mem,date:S.f.ab_d,time:S.f.ab_t,type:S.f.ab_type||'lesson',memo:S.f.ab_memo||''});clearF('ab_');closeModal();toast('예약을 추가했어요')};
