function vAContent(){const cur=subOf('content','video');const nv=S.formvids.filter(v=>v.status!=='reviewed').length;
 return `<h1>콘텐츠</h1>${seg('content',[['video','정보 영상'],['lib','운동 사전'],['fv',`회원 영상${nv?` ${nv}`:''}`],['notice','공지']],'video')}${cur==='lib'?libSec(true):cur==='fv'?formVidSec(null,true):cur==='notice'?noticeAdmin():videoAdmin()}`}
function videoAdmin(){const vc=S.f.vf_cat||'exercise';const Y=S.yt||{};const added=new Set(S.videos.filter(v=>v.cat===vc).map(v=>ytId(v.url)).filter(Boolean));
 const vrow=v=>`<div class="ytv"><img src="${esc(v.thumb)}" alt="" loading="lazy"><div class="grow"><div class="sm b ytt">${esc(v.title)}</div><div class="xs muted">${v.channel?esc(v.channel)+' · ':''}${v.at?String(v.at).slice(0,10):''}</div></div>${added.has(v.id)?'<span class="chip g xs">추가됨</span>':`<button class="btn sm pri" data-a="ytAdd" data-id="${v.id}" ${dis('yta'+v.id)}>${bz('yta'+v.id,'추가','…')}</button>`}</div>`;
 const fmtN=n=>n==null?'':n>=10000?(n/10000).toFixed(n>=100000?0:1)+'만':n.toLocaleString();
 return `<div class="card col"><h3>유튜브 영상 추가</h3>
 <div><label class="fl">어느 카테고리에 넣을까요?</label><div class="seg">${Object.entries(VC).map(([k,l])=>`<button class="${vc===k?'on':''}" data-a="vfCat" data-v="${k}">${l}</button>`).join('')}</div></div>
 <div class="row nw"><input class="inp" placeholder="유튜브 채널 이름 (예: 피지컬갤러리)" data-f="yt_q" value="${esc(fv('yt_q'))}" enterkeyhint="search"><button class="btn pri" data-a="ytSearch" ${dis('yts')}>${bz('yts',ic('search',16)+' 검색','…')}</button></div>
 ${Y.nokey?`<div class="note w"><b>유튜브 검색 키 등록이 필요해요 (무료, 한 번만)</b><br>① console.cloud.google.com → 새 프로젝트 만들기<br>② "API 및 서비스 → 라이브러리"에서 <b>YouTube Data API v3</b> 사용 설정<br>③ "사용자 인증 정보 → API 키 만들기"로 키 복사<br>④ Supabase → Edge Functions → Secrets에 이름 <b>YOUTUBE_API_KEY</b>로 저장<br>그동안은 아래 '링크로 직접 추가'를 써주세요.</div>`:''}
 ${Y.err?`<div class="err">${esc(Y.err)}</div>`:''}
 ${Y.ch?`<div class="row sb nw ytch on"><div class="row nw" style="gap:10px"><img src="${esc(Y.ch.thumb)}" alt=""><div><b>${esc(Y.ch.title)}</b><div class="xs muted">${Y.ch.info?esc(Y.ch.info)+' · ':''}${Y.ch.subs?'구독자 '+fmtN(Y.ch.subs)+' · ':''}${Y.ch.videos?'영상 '+fmtN(Y.ch.videos)+'개':''}</div></div></div><button class="btn sm ghost" data-a="ytBack">다른 채널</button></div>
  <div class="row nw"><input class="inp" placeholder="이 채널에서 검색 (예: 스쿼트)" data-f="yt_in" value="${esc(fv('yt_in'))}"><button class="btn" data-a="ytInSearch" ${dis('yti')}>${bz('yti','찾기','…')}</button></div>
  ${Y.inq?`<div class="row sb"><span class="xs muted">'${esc(Y.inq)}' 검색 결과</span><button class="btn sm ghost" data-a="ytChOpen" data-id="${Y.ch.id}">최신 영상 보기</button></div>`:'<div class="xs muted">최신 영상</div>'}
  ${S.busy.ytv&&!(Y.videos||[]).length?'<p class="sm"><span class="spin"></span> 영상을 불러오는 중…</p>':''}
  <div class="col" style="gap:8px">${(Y.videos||[]).map(vrow).join('')||(S.busy.ytv?'':'<p class="empty">영상이 없어요.</p>')}</div>
  ${Y.next?`<button class="btn ghost full" data-a="ytMore" ${dis('ytv')}>${bz('ytv','영상 더 보기','불러오는 중…')}</button>`:''}`
 :(Y.channels||[]).length?`<div class="col" style="gap:8px">${Y.channels.map(c=>`<div class="ytch tap" data-a="ytChOpen" data-id="${c.id}"><img src="${esc(c.thumb)}" alt=""><div class="grow"><b>${esc(c.title)}</b><div class="xs muted">${c.info?esc(c.info)+' · ':''}${c.subs?'구독자 '+fmtN(c.subs)+' · ':''}${c.videos?'영상 '+fmtN(c.videos)+'개':''}</div>${c.desc?`<div class="xs muted ell">${esc(c.desc)}</div>`:''}</div>${ic('right',18)}</div>`).join('')}</div>`:''}
 <details ${fv('vf_url')?'open':''}><summary class="sm muted">링크로 직접 추가</summary><div class="col" style="margin-top:8px"><input class="inp" placeholder="유튜브 링크 (https://youtu.be/...)" data-f="vf_url" value="${esc(fv('vf_url'))}"><input class="inp" placeholder="제목" data-f="vf_title" value="${esc(fv('vf_title'))}"><input class="inp" placeholder="한 줄 설명 (선택)" data-f="vf_desc" value="${esc(fv('vf_desc'))}"><button class="btn pri full" data-a="vidAdd">추가</button></div></details></div>
 <div class="card col"><div class="row sb"><h3>${VC[vc]} 영상 <span class="muted sm">${S.videos.filter(v=>v.cat===vc).length}편</span></h3><span class="xs muted">위에서 카테고리를 바꾸면 해당 영상만 보여요</span></div>${vList(S.videos.filter(v=>v.cat===vc),'a_'+vc,true)}</div>}`}
async function ytCall(qs){try{return await api('GET','/api/yt?'+new URLSearchParams(qs))}catch(e){throw e}}
function ytErr(e){S.yt={...(S.yt||{}),err:e.message,nokey:/키가 아직/.test(e.message)}}
A.ytSearch=()=>busy('yts',async()=>{const q=(S.f.yt_q||'').trim();if(!q)throw new Error('채널 이름을 입력해주세요.');S.yt={};try{const r=await ytCall({mode:'channels',q});S.yt={channels:r.channels||[]};if(!r.channels?.length)S.yt.err='채널을 찾지 못했어요. 이름을 다시 확인해주세요.'}catch(e){ytErr(e)}});
A.ytChOpen=({id})=>busy('ytv',async()=>{const Y=S.yt||{};const ch=(Y.channels||[]).find(c=>c.id===id)||Y.ch;S.yt={...Y,ch,videos:[],next:null,inq:'',err:''};delete S.f.yt_in;try{const r=await ytCall({mode:'videos',ch:id});S.yt={...S.yt,videos:r.videos||[],next:r.next,more:'videos'}}catch(e){ytErr(e)}});
A.ytInSearch=()=>busy('yti',async()=>{const Y=S.yt;const q=(S.f.yt_in||'').trim();if(!q)throw new Error('검색어를 입력해주세요.');try{const r=await ytCall({mode:'search',q,ch:Y.ch.id});S.yt={...Y,videos:r.videos||[],next:r.next,inq:q,more:'search',err:''}}catch(e){ytErr(e)}});
A.ytMore=()=>busy('ytv',async()=>{const Y=S.yt;try{const r=Y.more==='search'?await ytCall({mode:'search',q:Y.inq,ch:Y.ch.id,page:Y.next}):await ytCall({mode:'videos',ch:Y.ch.id,page:Y.next});S.yt={...Y,videos:[...(Y.videos||[]),...(r.videos||[])],next:r.next}}catch(e){ytErr(e)}});
A.ytBack=()=>{S.yt={...(S.yt||{}),ch:null,videos:[],next:null,inq:''};render()};
A.ytAdd=({id})=>busy('yta'+id,async()=>{const v=(S.yt?.videos||[]).find(x=>x.id===id);if(!v)return;const cat=S.f.vf_cat||'exercise';await put('videos',uid(),{cat,url:'https://youtu.be/'+id,title:v.title,desc:S.yt?.ch?.title||v.channel||'',createdAt:Date.now()});toast(`'${VC[cat]}'에 추가했어요`)});
A.vfCat=({v})=>{S.f.vf_cat=v;render()};
A.vidAdd=async()=>{const url=(S.f.vf_url||'').trim(),title=(S.f.vf_title||'').trim();if(!ytId(url)&&!/^https?:\/\//.test(url))return toast('올바른 링크를 입력해주세요');if(!title)return toast('제목을 입력해주세요');await put('videos',uid(),{cat:S.f.vf_cat||'exercise',url,title,desc:S.f.vf_desc||'',createdAt:Date.now()});['vf_url','vf_title','vf_desc'].forEach(k=>delete S.f[k]);toast('영상을 추가했어요')};
A.vidDel=async({id})=>{if(!await ask('영상을 삭제할까요?','','삭제',true))return;await delDoc('videos',id)};
function noticeAdmin(){return `<div class="card"><h3>${S.f.nt_edit?'공지 수정':'공지 작성'}</h3><input class="inp" placeholder="제목" data-f="nt_title" value="${esc(fv('nt_title'))}"><textarea class="inp" placeholder="내용" data-f="nt_body">${esc(fv('nt_body'))}</textarea><label class="row sm"><input type="checkbox" data-f="nt_pin" ${fv('nt_pin')?'checked':''}> 상단 고정</label><div class="row">${S.f.nt_edit?'<button class="btn" data-a="ntCancel">취소</button>':''}<button class="btn pri" style="flex:1" data-a="ntSave">${S.f.nt_edit?'수정':'등록'}</button></div></div>
 ${S.notices.map(n=>`<div class="card"><div class="row sb"><b>${n.pinned?'📌 ':''}${esc(n.title)}</b><span class="xs muted">${ago(n.createdAt)}</span></div><p class="sm" style="white-space:pre-wrap">${esc(n.body)}</p><div class="row"><button class="btn sm" data-a="ntEdit" data-id="${n.id}">수정</button><button class="btn sm ghost dng" data-a="ntDel" data-id="${n.id}">삭제</button></div></div>`).join('')}`}
A.ntSave=async()=>{const t=(S.f.nt_title||'').trim();if(!t)return toast('제목을 입력해주세요');const id=S.f.nt_edit||uid();const cur=S.notices.find(n=>n.id===id);await put('notices',id,{title:t,body:S.f.nt_body||'',pinned:!!S.f.nt_pin,createdAt:cur?.createdAt||Date.now()});clearF('nt_');toast('공지를 저장했어요')};
A.ntEdit=({id})=>{const n=S.notices.find(x=>x.id===id);Object.assign(S.f,{nt_edit:id,nt_title:n.title,nt_body:n.body,nt_pin:!!n.pinned});window.scrollTo(0,0);render()};
A.ntCancel=()=>{clearF('nt_');render()};A.ntDel=async({id})=>{if(!await ask('공지를 삭제할까요?','','삭제',true))return;await delDoc('notices',id)};
// ---- 설정 ----
function vASettings(){const st=S.settings;const a=me();return `<h1>설정</h1>${pushCard()}${calCard()}
 <div class="card"><h3>🔑 전용코드 변경</h3><p class="xs muted">보안을 위해 현재 코드는 표시되지 않아요. 바꾸면 즉시 적용되고, 이미 로그인한 사람은 그대로 유지돼요.</p>
 <div class="row nw"><input class="inp" placeholder="새 회원 전용코드" data-f="cd_m" value="${esc(fv('cd_m'))}" autocapitalize="off"><button class="btn pri" data-a="codeSave" data-k="m">변경</button></div>
 <div class="row nw"><input class="inp" placeholder="새 관리자 전용코드" data-f="cd_a" value="${esc(fv('cd_a'))}" autocapitalize="off"><button class="btn pri" data-a="codeSave" data-k="a">변경</button></div>${st.codeAt?`<div class="xs muted">마지막 변경 ${ago(st.codeAt)}</div>`:''}</div>
 <div class="card"><h3>📅 예약 설정</h3><div class="fg"><div><label class="fl">영업 시작</label><input class="inp" type="time" data-f="st_open" value="${esc(fv('st_open',st.open||'06:00'))}"></div><div><label class="fl">영업 종료</label><input class="inp" type="time" data-f="st_close" value="${esc(fv('st_close',st.close||'22:00'))}"></div>
 <div><label class="fl">예약 단위(분)</label><select class="inp" data-f="st_slot">${[30,50,60,90].map(x=>`<option ${+fv('st_slot',st.slotMin||60)===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label class="fl">변경·취소 마감(시간 전)</label><input class="inp" type="number" inputmode="numeric" data-f="st_cancel" value="${esc(fv('st_cancel',st.cancelHours??6))}"></div></div>
 <div><label class="fl">정기 휴무 요일</label><div class="daychk">${DOW.map((x,i)=>`<label><input type="checkbox" data-f="st_cd${i}" ${fv('st_cd'+i,(st.closedDays||[]).includes(i))?'checked':''}><span>${x}</span></label>`).join('')}</div></div>
 <label class="row sm"><input type="checkbox" data-f="st_auto" ${fv('st_auto',st.autoBlock!==false)?'checked':''}> 회차를 모두 쓰거나 종료일이 지난 회원은 자동으로 로그인 차단</label><button class="btn pri full" data-a="stSave">예약 설정 저장</button></div>
 <div class="card"><h3>📅 캘린더 연동 주소</h3>${icsBox(st.icsToken)}<button class="btn sm ghost" data-a="icsReset">주소 새로 만들기 (기존 주소 무효)</button></div>
 <div class="card"><h3>👤 관리자 계정</h3><div><label class="fl">아이디</label><input class="inp" data-f="ac_id" value="${esc(fv('ac_id',a.loginId))}" autocapitalize="off"></div><div><label class="fl">새 비밀번호 (바꿀 때만)</label><input class="inp" type="password" data-f="ac_pw1" value="${esc(fv('ac_pw1'))}"></div><div><label class="fl">새 비밀번호 확인</label><input class="inp" type="password" data-f="ac_pw2" value="${esc(fv('ac_pw2'))}"></div><div><label class="fl">현재 비밀번호 *</label><input class="inp" type="password" data-f="ac_pw0" value="${esc(fv('ac_pw0'))}"></div><button class="btn full" data-a="chgAcct">계정 정보 변경</button></div>
 <div class="card"><div class="row sb"><div><h3>👀 회원 화면으로 보기</h3><p class="xs muted">회원이 보는 화면 그대로 확인할 수 있어요. (미리보기라 저장은 안 돼요)</p></div><button class="btn soft" data-a="viewAs">전환</button></div></div>
 <div class="card"><div class="row sb"><h3>🎨 화면 모드</h3><button class="btn soft" data-a="theme">${S.theme==='dark'?'☀️ 라이트 모드':'🌙 다크 모드'}</button></div></div>
 <div class="card"><h3>✨ AI 기능</h3><p class="sm ${S.ai?'ok':'warn'} b">${S.ai?'AI 연결됨 — 루틴·식단·인바디·사진 분석 사용 가능':'AI 키가 아직 연결되지 않았어요'}</p>${S.ai?'':'<p class="xs muted">Supabase 대시보드 → Edge Functions → Secrets에 ANTHROPIC_API_KEY를 추가하면 AI 기능이 켜져요.</p>'}</div>
 <div class="card"><h3>로고</h3><div class="row">${LOGO(60)}<span class="word" style="font-size:34px">Core</span></div><p class="xs muted">Core = 몸의 중심(코어) + 우리 센터의 중심. 'C' 모양의 원판 안에 중심점을 담았어요.</p></div>
 <button class="btn ghost full" data-a="logout">${ic('out',16)} 로그아웃</button>`}
// ---- 아이폰 알림 (웹 푸시) ----
const NCATS=[['video','🎬 회원 영상 (업로드·답글)'],['book','📅 예약'],['cancel','✖️ 예약 취소'],['change','🔁 예약 변경'],['rereg','👤 재등록'],['workout','🏋️ 운동 기록·루틴'],['meal','🍽️ 식단 사진·기록'],['inbody','📊 인바디 업로드']];
const pushSupported=()=>'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window;
const isStandalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const isIOS=()=>/iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
async function pushState(){const o={sup:pushSupported(),perm:'Notification' in window?Notification.permission:'unsupported',on:false};try{if(o.sup){const r=await navigator.serviceWorker.getRegistration();const s=r&&await r.pushManager.getSubscription();o.on=!!s}const c=await api('GET','/api/push/count');o.n=c.n}catch(e){}S.push=o;schedule()}
function pushCard(){if(!S.push){pushState();}const p=S.push||{};const st=S.settings.notify||{};
 const guide=isIOS()&&!isStandalone()?`<div class="note w">아이폰은 <b>홈 화면에 추가한 Core 앱</b>에서만 알림을 받을 수 있어요 (iOS 16.4 이상).<br>① 사파리 아래 <b>공유</b> 버튼 → <b>홈 화면에 추가</b><br>② 홈 화면의 <b>Core</b> 아이콘으로 열고 로그인<br>③ 설정에서 다시 이 버튼을 눌러주세요</div>`:!p.sup?`<div class="note w">이 브라우저는 알림을 지원하지 않아요. 아이폰은 홈 화면에 추가한 Core 앱에서 켜주세요.</div>`:'';
 return `<div class="card"><h3>🔔 내 휴대폰으로 회원 소식 알림</h3><p class="xs muted">회원이 예약·취소·변경하거나 운동 기록·식단 사진·영상을 올리면 바로 알려드려요.</p>
 ${guide}
 ${p.sup&&(!isIOS()||isStandalone())?(p.on?`<div class="row sb"><span class="sm ok b">✅ 이 기기에서 알림 켜짐</span><button class="btn sm ghost" data-a="pushOff">끄기</button></div><button class="btn soft full" data-a="pushTest" ${dis('ptest')}>${bz('ptest','테스트 알림 보내기')}</button>`
  :p.perm==='denied'?`<div class="note w">알림이 차단돼 있어요. 아이폰 <b>설정 → 알림 → Core</b>에서 알림 허용을 켠 뒤 다시 눌러주세요.</div><button class="btn grad full" data-a="pushOn" ${dis('pon')}>${bz('pon','이 기기에서 알림 켜기')}</button>`
  :`<button class="btn grad lg full" data-a="pushOn" ${dis('pon')}>${bz('pon','🔔 이 기기에서 알림 켜기')}</button>`):''}
 ${p.n?`<p class="xs muted">알림 받는 기기 ${p.n}대</p>`:''}
 <div class="sec"><h4>받을 알림</h4><div class="list">${NCATS.map(([k,l])=>`<label class="li" style="cursor:pointer"><span class="grow sm">${l}</span><input type="checkbox" data-a="pushCat" data-k="${k}" ${st[k]!==false?'checked':''}></label>`).join('')}</div></div></div>`}
const b64uToU8=s=>{s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return Uint8Array.from(atob(s),c=>c.charCodeAt(0))};
A.pushOn=()=>busy('pon',async()=>{if(!pushSupported())throw new Error('이 브라우저는 알림을 지원하지 않아요.');
 const perm=await Notification.requestPermission();if(perm!=='granted'){await pushState();throw new Error('알림 허용이 필요해요. 설정 → 알림 → Core에서 허용해주세요.')}
 const reg=await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;const {key}=await api('GET','/api/push/key');
 let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64uToU8(key)});
 await api('POST','/api/push/sub',{sub:sub.toJSON(),ua:navigator.userAgent});await pushState();toast('알림을 켰어요! 테스트 알림을 보내볼까요?')});
A.pushOff=async()=>{try{const r=await navigator.serviceWorker.getRegistration();const s=r&&await r.pushManager.getSubscription();if(s){await api('POST','/api/push/unsub',{endpoint:s.endpoint});await s.unsubscribe()}}catch(e){}await pushState();toast('이 기기 알림을 껐어요')};
A.pushTest=()=>busy('ptest',async()=>{const r=await api('POST','/api/push/test');toast(`테스트 알림을 보냈어요 (${r.n}대)`)});
A.pushCat=async({k},el)=>{const cur={...(S.settings.notify||{})};cur[k]=el.checked;try{await act('admin/settings',{notify:cur});toast(el.checked?'알림을 켰어요':'이 알림은 받지 않아요')}catch(e){el.checked=!el.checked;throw e}};
A.codeSave=async({k})=>{const v=(S.f['cd_'+k]||'').trim();if(v.length<4)return toast('코드는 4자 이상으로 해주세요');await act('admin/codes',{[k==='m'?'member':'admin']:v});delete S.f['cd_'+k];toast(`${k==='m'?'회원':'관리자'} 전용코드를 '${v}'(으)로 바꿨어요`)};
A.stSave=async()=>{const st=S.settings;await act('admin/settings',{open:fv('st_open',st.open||'06:00'),close:fv('st_close',st.close||'22:00'),slotMin:+fv('st_slot',st.slotMin||60),cancelHours:+fv('st_cancel',st.cancelHours??6),closedDays:DOW.map((_,i)=>i).filter(i=>fv('st_cd'+i,(st.closedDays||[]).includes(i))),autoBlock:!!fv('st_auto',st.autoBlock!==false)});clearF('st_');toast('예약 설정을 저장했어요')};
A.icsReset=async()=>{if(!await ask('캘린더 주소를 새로 만들까요?','기존에 구독한 캘린더는 더 이상 갱신되지 않아요.','새로 만들기'))return;await act('admin/settings',{resetIcs:true})};

// ================= 시작 =================
async function boot(){applyTheme();S.boot=true;render();try{const st=await api('GET','/api/status');S.needSetup=st.setup;S.ai=st.ai;if(!st.setup)await loadMe().catch(()=>{})}catch(e){S.loginMsg=e.message}S.boot=false;render();hideSplash();
 setInterval(()=>{if(S.user&&document.visibilityState==='visible')sync().catch(()=>{})},20000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&S.user)sync().catch(()=>{})});
 const s=ls.get('core_ses');if(s&&S.user&&s.date===today()&&s.mid===S.user.id){S.ses=s;openModal(()=>sesView(),true)}}
boot();
document.addEventListener('keydown',e=>{if(e.key!=='Enter')return;const f=e.target.dataset&&e.target.dataset.f;if(f==='yt_q'){e.preventDefault();e.target.blur();A.ytSearch()}else if(f==='yt_in'){e.preventDefault();e.target.blur();A.ytInSearch()}});
// ---- 주간 일정 한 번에 예약 (관리자) ----
const monOf=s=>{const d=parseD(s);return addDays(s,-((d.getDay()+6)%7))};
A.wkOpen=({mem})=>{S.wk={mem:mem||'',start:addDays(monOf(today()),7),sel:[],type:'lesson'};openModal(wkModal)};
function wkModal(){const W=S.wk;const ms=members().filter(m=>mstate(m)==='active').sort((a,b)=>a.name.localeCompare(b.name));const m=W.mem&&S.members[W.mem];
 const days=[...Array(7)].map((_,i)=>addDays(W.start,i));const now=new Date();
 const fut=m?S.bookings.filter(b=>b.memberId===m.id&&b.status==='booked'&&b.type==='lesson'&&slotDT(b.date,b.time)>now).length:0;const left=m?remaining(m)-fut:0;
 const lessons=W.type==='lesson'?W.sel.length:0;
 const prev=m?S.bookings.filter(b=>b.memberId===m.id&&b.date>=addDays(W.start,-7)&&b.date<W.start&&b.status!=='noshow'):[];
 return `${mh('주간 일정 한 번에 예약')}
 <div><label class="fl">회원</label><select class="inp" data-f="wk_mem" onchange="A.wkMem({v:this.value})"><option value="">회원 선택</option>${ms.map(x=>`<option value="${x.id}" ${W.mem===x.id?'selected':''}>${esc(x.name)} (잔여 ${remaining(x)}회)</option>`).join('')}</select></div>
 <div class="row sb nw"><button class="ib" data-a="wkWeek" data-v="-7">${ic('left',18)}</button><b>${fmtD(days[0]).replace(/ \(.\)/,'')} ~ ${fmtD(days[6]).replace(/ \(.\)/,'')}</b><button class="ib" data-a="wkWeek" data-v="7">${ic('right',18)}</button></div>
 <div class="seg"><button class="${W.type==='lesson'?'on':''}" data-a="wkType" data-v="lesson">PT 수업</button><button class="${W.type==='consult'?'on':''}" data-a="wkType" data-v="consult">PT 상담</button></div>
 ${m&&prev.length?`<button class="btn soft full" data-a="wkCopy">${ic('refresh',15)} 지난주와 같은 요일·시간으로 (${prev.map(b=>'일월화수목금토'[parseD(b.date).getDay()]+' '+b.time).join(', ')})</button>`:''}
 ${m?'':'<p class="sm muted">회원을 먼저 선택해주세요.</p>'}
 <div class="col wkdays" style="gap:10px;${m?'':'opacity:.4;pointer-events:none'}">${days.map(dt=>{const closed=dayClosed(dt);const sl=slotsFor();
  return `<div><div class="xs b" style="margin-bottom:5px">${fmtD(dt)}${closed?' <span style="color:var(--hot)">휴무</span>':''}</div>${closed?'':`<div class="wkts">${sl.map(t=>{const id=sid(dt,t);const b=S.bookingMap[id];const k=dt+'|'+t;const on=W.sel.includes(k);const mine=b&&b.memberId===W.mem;const dis=(!!b&&b.status!=='cancel')||S.blocks[id]||slotDT(dt,t)<now;
   return `<button class="wkt ${on?'on':''} ${mine?'mine':''}" ${dis?'disabled':''} data-a="wkTog" data-k="${k}" title="${b?esc(nm(b.memberId)):''}">${t}${mine?' ✓':b?'<small>'+esc(nm(b.memberId)).slice(0,3)+'</small>':''}</button>`}).join('')}</div>`}</div>`}).join('')}</div>
 ${m?`<p class="xs muted">✓ 표시는 이미 잡힌 이 회원 예약, 회색은 다른 회원 예약이나 막힌 시간이에요. 남은 예약 가능 수업: <b>${left}회</b>${lessons>left?` <span style="color:var(--hot)">· 선택한 수업이 잔여보다 많아요</span>`:''}</p>`:''}
 <button class="btn grad full wksave" data-a="wkSave" ${!m||!W.sel.length?'disabled':''} ${dis('wks')}>${bz('wks',`${W.sel.length?W.sel.length+'건 ':''}예약하기`,'예약하는 중…')}</button>`}
A.wkMem=({v})=>{S.wk.mem=v;S.wk.sel=[];renderModal()};
A.wkWeek=({v})=>{S.wk.start=addDays(S.wk.start,+v);S.wk.sel=[];renderModal()};
A.wkType=({v})=>{S.wk.type=v;renderModal()};
A.wkTog=({k})=>{const s=S.wk.sel;S.wk.sel=s.includes(k)?s.filter(x=>x!==k):[...s,k].sort();renderModal()};
A.wkCopy=()=>{const W=S.wk;const now=new Date();const prev=S.bookings.filter(b=>b.memberId===W.mem&&b.date>=addDays(W.start,-7)&&b.date<W.start&&b.status!=='noshow');const add=[];
 for(const b of prev){const dt=addDays(b.date,7);const id=sid(dt,b.time);if(!S.bookingMap[id]&&!S.blocks[id]&&!dayClosed(dt)&&slotDT(dt,b.time)>now)add.push(dt+'|'+b.time)}
 S.wk.sel=[...new Set([...W.sel,...add])].sort();if(add.length<prev.length)toast(`${prev.length-add.length}건은 이미 찼거나 막힌 시간이라 빼고 골랐어요`);renderModal()};
A.wkSave=()=>busy('wks',async()=>{const W=S.wk;const ok=[],bad=[];
 for(const k of W.sel){const [date,time]=k.split('|');try{await api('POST','/api/book',{memberId:W.mem,date,time,type:W.type});ok.push(k)}catch(e){bad.push(`${fmtD(date)} ${time}: ${e.message}`)}}
 await sync();render();S.wk.sel=W.sel.filter(k=>!ok.includes(k));
 if(!bad.length){closeModal();toast(`${nm(W.mem)}님 ${ok.length}건 예약했어요`)}else{renderModal();await ask(`${ok.length}건 예약, ${bad.length}건 실패`,bad.join('\n'),'확인')}});
// ---- 캘린더 자동 예약 (관리자) ----
const calS=()=>C('calsync').get('main')||{};
function calCard(){const c=calS();const on=c.connected;const ago2=c.at?ago(c.at):'';
 return `<div class="card col" id="calcard"><div class="row sb"><h3>📅 캘린더로 자동 예약</h3>${on?`<span class="chip ${c.ok===false?'r':'g'} xs">${c.ok===false?'확인 필요':'연결됨'}</span>`:''}</div>
 <p class="sm muted">평소 쓰는 캘린더에 <b>"PT 홍길동"</b>, <b>"그룹 PT 김명숙/김은서"</b>처럼 적으면 몇 분 안에 그 회원 예약이 자동으로 잡혀요. 앱에 등록되지 않은 이름은 넣지 않아요.</p>
 ${on?`<div class="sm">연결된 캘린더: <b>${esc(c.hint||'')}</b>${ago2?` · 마지막 확인 ${ago2}`:''}</div>
  ${c.ok===false?`<div class="err">${esc(c.err||'')}</div>`:c.at?`<div class="xs muted">다가오는 PT 일정 ${c.events||0}개 · 새로 예약 ${c.added||0} · 시간 변경 ${c.moved||0} · 앱 미등록 이름 ${c.skipped||0}개 건너뜀</div>`:''}
  ${(c.removed||[]).length?`<div class="note w"><b>캘린더에서 지워진 일정이 있어요</b><br>예약은 그대로 두었어요. 취소할지 정해주세요.</div>${c.removed.map(r=>`<div class="bk"><div class="t num">${r.date.slice(5).replace('-','/')}<br>${r.time}</div><div class="grow sm b">${esc(r.name)}</div><button class="btn sm ghost dng" data-a="calCancel" data-h="${r.hid}" ${dis('cc'+r.hid)}>예약 취소</button><button class="btn sm soft" data-a="calKeep" data-h="${r.hid}">유지</button></div>`).join('')}`:''}
  ${(c.issues||[]).length?`<details><summary class="sm b" style="color:var(--hot)">확인이 필요한 일정 ${c.issues.length}개</summary>${c.issues.map(i=>`<div class="sm" style="margin-top:6px">• ${i.date.slice(5).replace('-','/')} ${i.time} "${esc(i.title)}" — ${esc(i.msg)}</div>`).join('')}</details>`:''}
  <div class="row nw"><button class="btn pri" style="flex:1" data-a="calRun" ${dis('calr')}>${bz('calr',ic('refresh',15)+' 지금 확인','확인 중…')}</button><button class="btn ghost" data-a="calEdit">링크 변경</button><button class="btn ghost dng" data-a="calOff">끊기</button></div>`:''}
 ${!on||S.f.cal_edit?`<input class="inp" placeholder="webcal://p00-caldav.icloud.com/published/…" data-f="cal_url" value="${esc(fv('cal_url'))}" autocapitalize="off" autocorrect="off"><button class="btn grad full" data-a="calSave" ${dis('cals')}>${bz('cals','연결하고 바로 확인','연결 중…')}</button>
  <details ${on?'':'open'}><summary class="sm b">공개 링크 복사하는 법 (iCloud '중요일정')</summary><div class="sm" style="line-height:1.7;margin-top:6px">① 아이폰 기본 <b>캘린더</b> 앱 실행<br>② 아래쪽 <b>캘린더</b> 버튼 → <b>중요일정</b> 옆 <b>ⓘ</b><br>③ 맨 아래 <b>공개 캘린더</b> 켜기<br>④ 나타난 <b>링크 공유…</b> → <b>복사</b><br>⑤ 여기 칸에 붙여넣고 '연결하고 바로 확인'<br><span class="xs muted">링크를 아는 사람은 이 캘린더 일정을 볼 수 있으니 다른 곳에 공유하지 마세요.</span></div></details>`:''}
 </div>`}
A.calEdit=()=>{S.f.cal_edit=1;render()};
A.calSave=()=>busy('cals',async()=>{const u=(S.f.cal_url||'').trim();if(!u)return toast('캘린더 공개 링크를 붙여넣어 주세요');try{const r=await act('admin/cal',{url:u});delete S.f.cal_url;delete S.f.cal_edit;toast(`연결했어요 · 새 예약 ${r.added||0}건`)}catch(e){await sync();render();toast(e.message)}});
A.calRun=()=>busy('calr',async()=>{try{const r=await act('admin/cal',{});toast(r.added||r.moved?`새 예약 ${r.added}건 · 변경 ${r.moved}건`:'새로 바뀐 일정이 없어요')}catch(e){await sync();render();toast(e.message)}});
A.calOff=async()=>{if(!await ask('캘린더 연결을 끊을까요?','이미 잡힌 예약은 그대로 남아요.','끊기',true))return;await act('admin/cal',{off:true});toast('연결을 끊었어요')};
A.calKeep=async({h})=>{await act('admin/cal',{keep:h});toast('예약을 유지했어요')};
A.calCancel=({h})=>busy('cc'+h,async()=>{await act('admin/cal',{cancel:h});toast('예약을 취소했어요')});
A.goCal=()=>{S.tab='settings';render();setTimeout(()=>document.getElementById('calcard')?.scrollIntoView({behavior:'smooth'}),80)};

// ---- 시작 로고 화면 ----
function hideSplash(){const el=document.getElementById('splash');if(!el||el.dataset.h)return;el.dataset.h=1;const wait=Math.max(0,380-(Date.now()-(window.__t0||0)));setTimeout(()=>{el.classList.add('out');setTimeout(()=>el.remove(),260)},wait)}
setTimeout(hideSplash,7000);

function srcBox(D){const sr=D.source||{};if(sr.fileId)return `<a class="btn full" href="${fileUrl(sr.fileId)}" target="_blank" rel="noopener">${ic('file',16)} 원본 파일 보기 (${esc(sr.name||'')})</a>`;if(sr.text)return `<details class="card"><summary class="sm b">${ic('file',14)} 원본 문서 내용 보기 (${esc(sr.name||'')})</summary><div class="sm" style="white-space:pre-wrap;margin-top:8px">${esc(sr.text)}</div></details>`;return ''}

A.mfTog=({k})=>{S.mfOpen={...(S.mfOpen||{}),[k]:!(S.mfOpen||{})[k]};render()};
